INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l01',3,1,1,'The Mountain Lion','美洲狮','过去叙事时态:一般过去时(叙事主干、发生完成的动作) vs 过去进行时(过去某刻正在进行的背景动作),以及 when(短促打断→一般过去)与 while(持续背景/两动作同时→过去进行)的辨析(原创承载 NCE3 L1 考点·美国小镇目击美洲狮)','去年秋天,科罗拉多一个小镇附近有人看见一头美洲狮在游荡。起初没人相信,但证据慢慢多了起来。一天早上,一位女士正沿着安静的小径遛狗,忽然发现那只大猫正卧在松树下。她吓得一动不动,那只动物则从阴影里一直盯着她。很快更多人报告见到了美洲狮——有人发现新鲜爪印,有人发现挂在栅栏上的毛。小镇觉得必须行动,于是官员组织了一次谨慎的搜寻。护林员在山里搜寻时,美洲狮却悄悄往相反方向走。好几天都找不到它,踪迹总是断掉。一头没被捕获、又饿的大猫离家这么近,让所有人都很不安。最后,美洲狮自己回到了山里,小镇又慢慢恢复了平静。','{"q":"Listen and answer — What animal was seen near the town?","options":["A mountain lion (puma)","A brown bear","A gray wolf","A wild horse"],"answer_index":0}'::jsonb,'{"title":"过去叙事的两把刷子:一般过去时 & 过去进行时","intro":"讲过去的故事,常靠两种时态配合:①一般过去时——讲一件件发生、已经完成的动作,是叙事的主干(spotted、found、organized、wandered);②过去进行时(was/were + doing)——讲过去某个时刻正在进行、用来当背景的动作(was walking、were searching、was watching)。when 后常接一个短促、打断背景的动作(一般过去);while 后常接一个持续的背景动作(过去进行);两个同时持续的动作,可以都用过去进行(While the rangers were searching, the lion was moving).","table":{"headers":["时态","用来讲","例子"],"rows":[["一般过去时","一件件发生、已完成的动作(叙事主干)","spotted the cat / found prints / organized a hunt"],["过去进行时","过去某刻正在进行的背景动作","was walking / were searching / was watching"],["when + 一般过去","短促、打断背景的那个动作","When she saw the cat, she froze."],["while + 过去进行","持续的背景 / 两个动作同时进行","While she was walking, she spotted it."]]},"specialRules":[{"rule":"when 常带出一个短促、打断性的动作(用一般过去);while 常带出一个持续的背景动作(用过去进行)。两件事同时在进行,两边都用过去进行。","mark":"when / while"},{"rule":"美语里这种大猫常叫 mountain lion 或 cougar,和 puma 是同一种动物;“秋天”美语说 fall(英式 autumn)。本课已按美语写。","mark":"mountain lion / fall"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l01',1,NULL,'Last fall, a mountain lion was seen wandering near a small town in Colorado. At first, people did not believe the reports, but the evidence slowly accumulated.','去年秋天,科罗拉多一个小镇附近有人看见一头美洲狮在游荡。起初,人们不相信这些报告,但证据慢慢积累起来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l01',2,NULL,'One morning, while a woman was walking her dog along a quiet trail, she spotted the big cat resting under a pine tree. She stood completely still while the animal was watching her from the shadows.','一天早上,一位女士正沿着安静的小径遛狗,忽然发现那只大猫正卧在一棵松树下。她一动不动地站着,那只动物则从阴影里一直盯着她。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l01',3,NULL,'Soon, more people reported seeing the puma; some found fresh paw prints, and others found fur clinging to their fences.','很快,更多人报告见到了这头美洲狮;有人发现了新鲜的爪印,有人发现毛挂在自家栅栏上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l01',4,NULL,'The town felt obliged to act, so the officials organized a careful hunt. While the rangers were searching the hills, the mountain lion was moving quietly in the opposite direction.','小镇觉得必须行动,于是官员们组织了一次谨慎的搜寻。护林员们正在山里搜寻时,美洲狮却悄悄地朝相反方向走。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l01',5,NULL,'For several days, no one could find it, because the trail always seemed to disappear. The thought of an unhunted, hungry cat so close to their homes was disturbing to everyone. In the end, the puma wandered back into the mountains, and the town slowly returned to its quiet life.','一连好几天都没人能找到它,因为踪迹总是断掉。一头没被捕获、又饥饿的大猫离家这么近,这想法让所有人都很不安。最后,美洲狮自己漫步回到了山里,小镇也慢慢恢复了平静。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
