INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l01','catch sight of','',NULL,'/kætʃ saɪt əv/','She caught sight of the puma under a tree.','她瞥见树下有头美洲狮。','I caught sight of my friend at the door.','我在门口瞥见了我的朋友。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l01','feel obliged to','',NULL,'/fiːl əˈblaɪdʒd tuː/','The town felt obliged to act.','小镇觉得必须采取行动。','I felt obliged to help my neighbor.','我觉得自己有义务帮邻居。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l01','cling to','',NULL,'/klɪŋ tuː/','Fur was clinging to the fence.','毛挂在栅栏上。','The child clung to her mother.','孩子紧紧抱着妈妈。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l01','in the opposite direction','',NULL,'/ɪn ði ˈɑːpəzɪt dəˈrekʃn/','The lion moved in the opposite direction.','狮子朝相反方向走。','They ran in the opposite direction.','他们朝相反方向跑。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp1','choice','{"stem":"\"Last fall, people ___ a mountain lion near the town.\"(叙事主干:已经发生、完成的动作)","options":["have spotted","spotted","spot","were spotting"],"answer_index":1,"stem_cn":"去年秋天,人们在镇子附近看见了一头美洲狮。","explanation_cn":"讲一件已经发生、完成的事,是叙事的主干,用一般过去时。✓ people spotted a mountain lion. ✗ were spotting:这里不是强调“当时正在……”的背景;✗ spot:没变过去式;✗ have spotted:讲过去某个明确时间(last fall)发生的事,不用现在完成。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp1','choice','{"stem":"\"The town ___ a careful hunt to find the animal.\"(叙事主干:已经发生、完成的动作)","options":["organized","was organizing","organizes","organize"],"answer_index":0,"stem_cn":"小镇组织了一次谨慎的搜寻来找那只动物。","explanation_cn":"“组织了一次搜寻”是发生并完成的动作,叙事主干,用一般过去时。✓ organized a hunt. ✗ was organizing:不是当背景的进行动作;✗ organizes:现在时不对;✗ organize:没变过去式。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp1','choice','{"stem":"\"Some people ___ fresh paw prints near the fence.\"(发生完成的动作,不规则过去式)","options":["were finding","find","have found","found"],"answer_index":3,"stem_cn":"有些人在栅栏附近发现了新鲜的爪印。","explanation_cn":"find 的过去式是不规则的 found;“发现了爪印”是完成的动作,用一般过去时。✓ found fresh paw prints. ✗ were finding / find / have found:这里讲过去发生完成的一件事,用一般过去。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp1','choice','{"stem":"\"In the end, the puma ___ back into the mountains.\"(叙事收尾:发生完成的动作)","options":["was wandering","wanders","wandered","wander"],"answer_index":2,"stem_cn":"最后,美洲狮漫步回到了山里。","explanation_cn":"故事收尾“回到了山里”是发生完成的动作,用一般过去时。✓ the puma wandered back. ✗ was wandering:不是当时正在进行的背景;✗ wanders / wander:时态不对。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp2','choice','{"stem":"\"One morning, a woman ___ her dog along a quiet trail.\"(当时正在进行的背景动作)","options":["was walking","walks","has walked","walked"],"answer_index":0,"stem_cn":"一天早上,一位女士正沿着安静的小径遛狗。","explanation_cn":"“一天早上正沿着小径遛狗”是当时正在进行、给后面事情当背景的动作,用过去进行时。✓ a woman was walking her dog. ✗ walked:一般过去讲的是完成的动作,这里要强调“正在进行”;✗ walks / has walked:时态不对。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp2','choice','{"stem":"\"While the rangers ___ the hills, the cat slipped away.\"(持续的背景动作,复数主体)","options":["searched","were searching","are searching","search"],"answer_index":1,"stem_cn":"护林员们正在搜山的时候,那只猫溜走了。","explanation_cn":"“护林员正在搜山”是那段时间持续进行的背景,主体是复数,用 were + doing。✓ the rangers were searching. ✗ searched:强调的是持续背景,不是完成动作;✗ are searching / search:时态不对。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp2','choice','{"stem":"\"At that moment, the animal ___ her from under a tree.\"(过去某一刻正在进行的动作)","options":["was watching","watched","watches","had watched"],"answer_index":0,"stem_cn":"那一刻,那只动物正从树下盯着她。","explanation_cn":"“那一刻正盯着她”是过去某个时刻正在进行的动作,用过去进行时。✓ the animal was watching her. ✗ watched:一般过去讲完成动作;✗ watches / had watched:时态不对。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp2','choice','{"stem":"\"The dog ___ loudly when the woman first saw the cat.\"(当时正在进行的背景动作)","options":["has barked","barked","was barking","barks"],"answer_index":2,"stem_cn":"女士第一次看见那只猫时,狗正在大声叫。","explanation_cn":"“当时狗正在大声叫”是背景动作,用过去进行时。✓ the dog was barking. ✗ barked:强调的是“正在叫”的背景;✗ barks / has barked:时态不对。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp3','choice','{"stem":"\"While she was walking her dog, she suddenly ___ the puma.\"(背景持续、被打断时,那个短促动作用一般过去)","options":["spots","spotted","was spotting","had spotted"],"answer_index":1,"stem_cn":"她正遛狗时,突然看见了美洲狮。","explanation_cn":"while 带出“正遛狗”的持续背景;“突然看见”是打断背景的那个短促动作,用一般过去时。✓ she suddenly spotted the puma. ✗ was spotting:短促的一下,不用进行;✗ spots / had spotted:时态不对。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp3','choice','{"stem":"\"When the woman ___ the cat, she froze at once.\"(一看见就……:短促打断的动作用一般过去)","options":["was seeing","had been seeing","saw","sees"],"answer_index":2,"stem_cn":"女士一看见那只猫,立刻僵住了。","explanation_cn":"when 带出一个短促、打断性的动作“一看见”,用一般过去时。✓ When the woman saw the cat. ✗ was seeing:see 表“看见”这一下不用进行;✗ sees / had been seeing:时态不对。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp3','choice','{"stem":"\"The rangers were climbing the hill when they ___ fresh tracks on the path.\"(正在进行时被打断:那个短促动作用一般过去)","options":["were finding","found","find","have found"],"answer_index":1,"stem_cn":"护林员们正在爬山,这时发现了小路上的新鲜踪迹。","explanation_cn":"“正在爬山”是背景,when 带出的“发现踪迹”是打断的短促动作,用一般过去时。✓ when they found fresh tracks. ✗ were finding:打断的一下不用进行;✗ find / have found:时态不对。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp4','choice','{"stem":"\"While the rangers were searching, the lion ___ in the opposite direction.\"(两个动作同时进行,都用过去进行)","options":["was moving","moves","has moved","moved"],"answer_index":0,"stem_cn":"护林员们在搜寻时,狮子正朝相反方向走。","explanation_cn":"护林员搜寻的同时,狮子也“正朝相反方向走”——两件事同时在进行,都用过去进行时。✓ the lion was moving away. ✗ moved:这里强调“同时正在进行”;✗ moves / has moved:时态不对。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp4','choice','{"stem":"\"While the townspeople were sleeping, the cat ___ quietly through the empty streets.\"(两个动作同时进行,都用过去进行)","options":["had walked","walks","walked","was walking"],"answer_index":3,"stem_cn":"镇上的人都在睡觉时,那只猫正悄悄穿过空荡荡的街道。","explanation_cn":"镇上人都在睡觉的同时,猫“正悄悄穿过街道”——两件事同时进行,都用过去进行时。✓ the cat was walking through the streets. ✗ walked:强调同时在进行;✗ walks / had walked:时态不对。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp5','choice','{"stem":"\"The evidence ___ day by day until the whole town believed it.\"(一步步完成的叙事动作:一般过去)","options":["accumulate","accumulated","accumulates","was accumulating"],"answer_index":1,"stem_cn":"证据一天天积累,直到全镇都相信了。","explanation_cn":"“证据一天天积累起来,直到全镇相信”是一步步发生、最终完成的叙事动作,用一般过去时。✓ the evidence accumulated. ✗ was accumulating:这里落点在“积累到了那个程度”的完成,不用进行;✗ accumulates / accumulate:时态不对。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp5','choice','{"stem":"\"She stood still while the animal ___ her.\"(持续的背景动作:过去进行)","options":["was watching","watch","watched","watches"],"answer_index":0,"stem_cn":"她一动不动地站着,那只动物一直盯着她。","explanation_cn":"while 带出“那只动物一直盯着她”的持续背景,用过去进行时。✓ while the animal was watching her. ✗ watched:强调持续的背景;✗ watches / watch:时态不对。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp6','choice','{"stem":"\"There was clear ___ that a big cat was nearby: prints, fur, and tracks.\"(证据用哪个词)","options":["weather","evidence","furniture","ticket"],"answer_index":1,"stem_cn":"有明显的证据表明附近有只大猫:足迹、毛和踪迹。","explanation_cn":"足迹、毛、踪迹这些能证明大猫在附近的“证据、迹象”是 evidence。✓ clear evidence that a big cat was nearby. ✗ weather 天气;✗ ticket 门票;✗ furniture 家具。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp6','choice','{"stem":"\"The rangers followed the ___ of paw prints up the hill.\"(小径、一串痕迹用哪个词)","options":["trail","market","garden","kitchen"],"answer_index":0,"stem_cn":"护林员们顺着一串爪印往山上追。","explanation_cn":"顺着追下去的“小径、一串痕迹”是 trail。✓ followed the trail of paw prints. ✗ garden 花园;✗ kitchen 厨房;✗ market 市场。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',5,'am3_l01_gp6','choice','{"stem":"\"The danger ___ the town to organize a hunt.\"(使……感到必须做,用哪个词)","options":["invited","allowed","reminded","obliged"],"answer_index":3,"stem_cn":"危险迫使小镇组织了一次搜寻。","explanation_cn":"“使某人感到必须做某事”是 oblige（sb to do）;这里“危险迫使小镇搜寻”。✓ The danger obliged the town to organize a hunt. ✗ invited 邀请;✗ allowed 允许;✗ reminded 提醒——都不表示“迫使、使不得不”。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',6,NULL,'choice','{"stem":"美语里这种大猫常叫:","options":["mountain lion","hill-tiger","snow-cat","wild-dog"],"answer_index":0,"explanation_cn":"美语里这种大猫常叫 mountain lion(也叫 cougar),和 puma 是同一种动物。✓ a mountain lion, or puma."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',6,NULL,'choice','{"stem":"美语里\"秋天\"说:","options":["harvest-time","cold-season","fall","autumn"],"answer_index":2,"explanation_cn":"美语“秋天”说 fall;英式说 autumn。✓ Last fall, a puma was seen."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',6,NULL,'choice','{"stem":"evidence 的意思是:","options":["门票","家具","天气","证据"],"answer_index":3,"explanation_cn":"evidence = 证据、迹象。✓ the evidence accumulated 证据积累起来。\n顺带记:天气 = weather;家具 = furniture;门票 = ticket."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',6,NULL,'choice','{"stem":"spot(动词)的意思是:","options":["认出,发现","出售","丢失","打碎"],"answer_index":0,"explanation_cn":"spot(动词)= 认出、发现。✓ she spotted the big cat 她发现了那只大猫。\n顺带记:丢失 = lose;出售 = sell;打碎 = break."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',6,NULL,'choice','{"stem":"trail 的意思是:","options":["市场","小径;一串痕迹","花园","厨房"],"answer_index":1,"explanation_cn":"trail = 小径,也指一串痕迹。✓ a quiet trail 一条安静的小径;the trail of prints 一串足迹。\n顺带记:厨房 = kitchen;市场 = market;花园 = garden."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',6,NULL,'choice','{"stem":"disturbing 的意思是:","options":["很普通的","令人愉快的","很便宜的","令人不安的"],"answer_index":3,"explanation_cn":"disturbing = 令人不安的。✓ a disturbing thought 一个令人不安的念头。\n顺带记:令人愉快的 = pleasant;普通的 = ordinary;便宜的 = cheap."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',7,NULL,'cloze','{"stem":"第 1 空","context":"One morning, while a woman ___1___ her dog, she ___2___ a mountain lion under a tree. She stood still while the animal ___3___ her. Later, the officials ___4___ a careful hunt, but no one could find the cat.","blank_no":1,"options":["walked","was walking","walks","has walked"],"answer_index":1,"explanation_cn":"“正遛狗”是给后面“看见猫”当背景的持续动作,用过去进行时。✓ while a woman was walking her dog."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',7,NULL,'cloze','{"stem":"第 2 空","context":"One morning, while a woman ___1___ her dog, she ___2___ a mountain lion under a tree. She stood still while the animal ___3___ her. Later, the officials ___4___ a careful hunt, but no one could find the cat.","blank_no":2,"options":["spotted","was spotting","spots","had spotted"],"answer_index":0,"explanation_cn":"在遛狗的背景下“忽然看见”是打断的短促动作,用一般过去时。✓ she spotted a mountain lion."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',7,NULL,'cloze','{"stem":"第 3 空","context":"One morning, while a woman ___1___ her dog, she ___2___ a mountain lion under a tree. She stood still while the animal ___3___ her. Later, the officials ___4___ a careful hunt, but no one could find the cat.","blank_no":3,"options":["watched","was watching","watches","watch"],"answer_index":1,"explanation_cn":"“那只动物一直盯着她”是持续的背景,用过去进行时。✓ while the animal was watching her."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',7,NULL,'cloze','{"stem":"第 4 空","context":"One morning, while a woman ___1___ her dog, she ___2___ a mountain lion under a tree. She stood still while the animal ___3___ her. Later, the officials ___4___ a careful hunt, but no one could find the cat.","blank_no":4,"options":["organized","were organizing","organize","have organized"],"answer_index":0,"explanation_cn":"“后来官员组织了一次搜寻”是发生完成的动作,叙事主干,用一般过去时。✓ the officials organized a careful hunt."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',8,NULL,'choice','{"stem":"What did the woman see while walking her dog?","options":["A wolf on the road","A deer in a field","A brown bear in a cave","A mountain lion under a tree"],"answer_index":3,"explanation_cn":"课文说 while a woman was walking her dog… she spotted the big cat resting under a pine tree——她看见一头美洲狮卧在树下。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',8,NULL,'choice','{"stem":"What did people find as evidence?","options":["Fresh paw prints and fur","Lost keys","Empty cans","Broken windows"],"answer_index":0,"explanation_cn":"课文说 some found fresh paw prints, and others found fur clinging to their fences——人们发现了新鲜爪印和挂在栅栏上的毛。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',8,NULL,'choice','{"stem":"How did the story end?","options":["The puma stayed in the town","The puma wandered back into the mountains","The puma was caught in a net","The puma attacked a ranger"],"answer_index":1,"explanation_cn":"课文说 In the end, the puma wandered back into the mountains——最后美洲狮自己回到了山里。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',9,NULL,'choice','{"stem":"你想说\"我正遛狗时看见了那只猫\"(正在进行的背景 + 短促打断的动作):","options":["I was walking my dog when I was seeing the cat.","I was walking my dog when I saw the cat.","I am walking my dog when I saw the cat.","I walked my dog when I was seeing the cat."],"answer_index":1,"explanation_cn":"“正遛狗”是持续背景用过去进行,“看见猫”是短促打断用一般过去。✓ I was walking my dog when I saw the cat. 场合:讲“我正做某事时,突然发生了另一件事”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',9,NULL,'choice','{"stem":"你想说\"护林员搜山时,狮子朝相反方向走\"(两个动作同时进行):","options":["While the rangers searched, the lion moved away and back.","While the rangers are searching, the lion was moving away.","While the rangers were searching, the lion was moving away.","While the rangers were searching, the lion moves away."],"answer_index":2,"explanation_cn":"两件事同时在进行,两边都用过去进行时。✓ While the rangers were searching, the lion was moving away. 场合:讲两件事在同一时间各自持续进行。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',9,NULL,'choice','{"stem":"你想说\"她一看见那只猫就僵住了\"(短促打断用一般过去):","options":["When she saw the cat, she froze.","When she saw the cat, she was freezing.","When she was seeing the cat, she froze.","When she sees the cat, she froze."],"answer_index":0,"explanation_cn":"“一看见”是短促打断的动作,“僵住”也是紧接着发生的动作,都用一般过去时。✓ When she saw the cat, she froze. 场合:讲“一……就……”两个先后发生的短动作。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',10,NULL,'choice','{"stem":"puma 的意思是:","options":["灰狼","美洲狮","棕熊","野马"],"answer_index":1,"explanation_cn":"puma = 美洲狮(美语又叫 mountain lion / cougar)。✓ a mountain lion, or puma."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',10,NULL,'choice','{"stem":"disturbing 的意思是:","options":["很便宜的","很普通的","令人愉快的","令人不安的"],"answer_index":3,"explanation_cn":"disturbing = 令人不安的。✓ a disturbing thought 令人不安的念头。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',10,NULL,'choice','{"stem":"\"While she ___ her dog, she saw the cat.\"(正在进行的背景动作)","options":["walked","was walking","has walked","walks"],"answer_index":1,"stem_cn":"她正遛狗时看见了那只猫。","explanation_cn":"“正遛狗”是给“看见猫”当背景的持续动作,用过去进行时。✓ While she was walking her dog."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',10,NULL,'choice','{"stem":"\"When the woman saw the cat, she ___ at once.\"(短促打断:一般过去)","options":["has frozen","was freezing","freezes","froze"],"answer_index":3,"stem_cn":"女士一看见那只猫就立刻僵住了。","explanation_cn":"freeze 的过去式是不规则的 froze;“一看见就僵住”是短促发生的动作,用一般过去时。✓ she froze at once. ✗ was freezing / freezes / has frozen:时态不对。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',10,NULL,'choice','{"stem":"\"feel obliged to\" 的意思是:","options":["忘记(做)","拒绝(做)","觉得必须(做)","乐意(做)"],"answer_index":2,"explanation_cn":"feel obliged to = 觉得(自己)必须做、有义务做。✓ The town felt obliged to act. 小镇觉得必须行动。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',10,NULL,'choice','{"stem":"\"in the opposite direction\" 的意思是:","options":["在半路上","在原地","朝同一方向","朝相反方向"],"answer_index":3,"explanation_cn":"in the opposite direction = 朝相反方向。✓ The lion moved in the opposite direction. 狮子朝相反方向走。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',10,NULL,'choice','{"stem":"Where did the woman first spot the mountain lion?","options":["Resting under a pine tree","On a rooftop","In a river","Inside a barn"],"answer_index":0,"passage":"Last fall, a mountain lion was seen wandering near a small town in Colorado. At first, people did not believe the reports, but the evidence slowly accumulated. One morning, while a woman was walking her dog along a quiet trail, she spotted the big cat resting under a pine tree. She stood completely still while the animal was watching her from the shadows. Soon, more people reported seeing the puma; some found fresh paw prints, and others found fur clinging to their fences. The town felt obliged to act, so the officials organized a careful hunt. While the rangers were searching the hills, the mountain lion was moving quietly in the opposite direction. For several days, no one could find it, because the trail always seemed to disappear. The thought of an unhunted, hungry cat so close to their homes was disturbing to everyone. In the end, the puma wandered back into the mountains, and the town slowly returned to its quiet life.","explanation_cn":"课文说 she spotted the big cat resting under a pine tree——她第一次看见它是卧在一棵松树下。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',10,NULL,'choice','{"stem":"Why did the town organize a hunt?","options":["They wanted to hold a festival","They were simply bored","A dangerous cat was near their homes","They had lost a pet"],"answer_index":2,"passage":"Last fall, a mountain lion was seen wandering near a small town in Colorado. At first, people did not believe the reports, but the evidence slowly accumulated. One morning, while a woman was walking her dog along a quiet trail, she spotted the big cat resting under a pine tree. She stood completely still while the animal was watching her from the shadows. Soon, more people reported seeing the puma; some found fresh paw prints, and others found fur clinging to their fences. The town felt obliged to act, so the officials organized a careful hunt. While the rangers were searching the hills, the mountain lion was moving quietly in the opposite direction. For several days, no one could find it, because the trail always seemed to disappear. The thought of an unhunted, hungry cat so close to their homes was disturbing to everyone. In the end, the puma wandered back into the mountains, and the town slowly returned to its quiet life.","explanation_cn":"课文说 The town felt obliged to act… a hungry cat so close to their homes was disturbing——因为一头危险的大猫离家太近,小镇才组织搜寻。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',10,NULL,'choice','{"stem":"What evidence did people find?","options":["Paw prints and fur","Only footprints in snow","A clear photograph","Nothing at all"],"answer_index":0,"audio":"Last fall, a mountain lion was seen wandering near a small town in Colorado. At first, people did not believe the reports, but the evidence slowly accumulated. One morning, while a woman was walking her dog along a quiet trail, she spotted the big cat resting under a pine tree. She stood completely still while the animal was watching her from the shadows. Soon, more people reported seeing the puma; some found fresh paw prints, and others found fur clinging to their fences. The town felt obliged to act, so the officials organized a careful hunt. While the rangers were searching the hills, the mountain lion was moving quietly in the opposite direction. For several days, no one could find it, because the trail always seemed to disappear. The thought of an unhunted, hungry cat so close to their homes was disturbing to everyone. In the end, the puma wandered back into the mountains, and the town slowly returned to its quiet life.","explanation_cn":"课文说人们发现了 fresh paw prints 和 fur clinging to their fences——爪印和毛就是证据。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l01',10,NULL,'choice','{"stem":"What happened to the puma in the end?","options":["It hurt a person","It was never seen again with no trace","It was captured by rangers","It went back into the mountains"],"answer_index":3,"audio":"Last fall, a mountain lion was seen wandering near a small town in Colorado. At first, people did not believe the reports, but the evidence slowly accumulated. One morning, while a woman was walking her dog along a quiet trail, she spotted the big cat resting under a pine tree. She stood completely still while the animal was watching her from the shadows. Soon, more people reported seeing the puma; some found fresh paw prints, and others found fur clinging to their fences. The town felt obliged to act, so the officials organized a careful hunt. While the rangers were searching the hills, the mountain lion was moving quietly in the opposite direction. For several days, no one could find it, because the trail always seemed to disappear. The thought of an unhunted, hungry cat so close to their homes was disturbing to everyone. In the end, the puma wandered back into the mountains, and the town slowly returned to its quiet life.","explanation_cn":"课文说 In the end, the puma wandered back into the mountains——它最后自己回到了山里。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l02',3,1,2,'Thirteen Is Close Enough','十三也差不多','两种现在时:一般现在时(习惯、反复、客观事实/规律) vs 现在进行时(此刻正在发生、这一阵临时在做),以及 always + 现在进行时(老是……,带抱怨/情绪)与一批 in 固定短语(in surprise / in a hurry / in the end / in trouble / in bed / in the dark)(原创承载 NCE3 L2 考点·美国小镇的老钟半夜敲十三下)','在我们镇上,市政厅上那座老钟老是惹麻烦。它日夜报时,大家都熟悉它那沉沉的钟声,镇上一直想筹钱把它修好,可钱总不够。奇怪的是:凌晨一点,这钟会敲十三下——其实就是一点,所以对这钟来说,十三等于一。多数夜里我躺在床上,惊讶地数着钟响。这一阵有件新鲜事:每晚钟楼里都有一点小灯在移动,有人半夜在上面忙活。今晚我终于抓起手电,穿过空荡荡的广场。借着手电光,我认出是照看隔壁小教堂、常给牧师帮忙的老戴尔先生。“这么晚你在上面干嘛?”我问。“我在修这口钟,”他轻声说,“这一阵我几乎每晚都上来。我不忍心看着全镇为一口老钟犯难。”戴尔先生年纪不小了,老是在鼓捣点什么,却从不放弃。到现在,钟还是敲十三下——可全镇学会了一笑,把它当成一点。','{"q":"Listen and answer — How many times does the clock strike at one o''clock?","options":["Thirteen times","Once","Twelve times","It does not strike at all"],"answer_index":0}'::jsonb,'{"title":"两种现在时:一般现在时 & 现在进行时","intro":"①一般现在时——讲习惯、反复发生的事、客观事实/规律(The clock strikes the hours. / Water boils at 100°.);②现在进行时(am/is/are + doing)——讲此刻正在发生、或这一阵临时在做的事(A light is moving now. / These days it is happening.)。特别注意:always/constantly + 现在进行时,表示“老是……”,往往带点抱怨或情绪(That clock is always causing trouble!)。再记一批要整体背的 in 短语:in surprise(惊讶地)、in a hurry(匆忙)、in the end(最后)、in trouble(有麻烦)、in bed(在床上)、in the dark(在黑暗中)。","table":{"headers":["用法","什么时候用","例子"],"rows":[["一般现在时","习惯、反复、客观事实/规律","The clock strikes the hours. / Water boils at 100°."],["现在进行时","此刻正在发生 / 这一阵临时在做","A light is moving now. / These days it is happening."],["always + 现在进行时","老是……(带抱怨/情绪)","That clock is always causing trouble!"],["in 短语(固定搭配)","一批要整体记的介词短语","in surprise / in a hurry / in the end / in trouble"]]},"specialRules":[{"rule":"看到 now, right now, at the moment, these days, Listen!, Look! 多用现在进行时;看到 every day, usually, often, always(讲习惯) 多用一般现在时。","mark":"now / every day"},{"rule":"always + 现在进行时 不是单纯讲习惯,而是“老是……”,带抱怨或情绪色彩(He is always losing his keys! 他老是丢钥匙!)。","mark":"always + doing"},{"rule":"手电筒美语常说 flashlight(英式 torch);torchlight 指“手电筒的光”。本课已按美语写。","mark":"flashlight / torch"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l02',1,NULL,'In our town, the old clock on the town hall is always causing trouble. It stands high above Main Street and strikes the hours day and night.','在我们镇上,市政厅上那座老钟老是惹麻烦。它高高立在大街上方,日夜报时。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l02',2,NULL,'Everyone knows its slow, heavy sound, and the town keeps trying to raise money to fix it. The strange thing is this: at one o''clock the clock strikes thirteen times.','大家都熟悉它那沉沉的、缓慢的钟声,镇上一直想筹钱把它修好。奇怪的是:凌晨一点,这钟会敲十三下。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l02',3,NULL,'It is really one o''clock, but for our clock, thirteen equals one. Most nights I lie in bed and count the strokes in surprise.','其实就是一点,可对我们这钟来说,十三等于一。多数夜里,我躺在床上,惊讶地数着钟响。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l02',4,NULL,'These days something new is happening. Every night a small light is moving inside the tower, and someone is working up there in the dark. Tonight I finally grab a flashlight and cross the empty square.','这一阵有件新鲜事:每晚钟楼里都有一点小灯在移动,有人半夜在上面忙活。今晚我终于抓起手电,穿过空荡荡的广场。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l02',5,NULL,'By the torchlight I recognize old Mr. Dale, who looks after the little church next door. ''I am trying to fix the bell,'' he says quietly. Mr. Dale is always working on something, but he never gives up.','借着手电光,我认出是照看隔壁小教堂的老戴尔先生。“我在修这口钟,”他轻声说。戴尔先生老是在鼓捣点什么,却从不放弃。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
