INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l02','wake up with a start','',NULL,'/weɪk ʌp wɪð ə stɑːrt/','I wake up with a start when the clock strikes.','钟一响,我惊醒过来。','She woke up with a start at the loud noise.','一声巨响,她惊醒了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l02','in surprise','',NULL,'/ɪn sərˈpraɪz/','I count the strokes in surprise.','我惊讶地数着钟响。','He looked at me in surprise.','他惊讶地看着我。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l02','in the end','',NULL,'/ɪn ðə end/','In the end, the town just smiles about the clock.','最后,全镇对这钟一笑了之。','In the end, we decided to stay home.','最后,我们决定待在家里。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l02','look after','',NULL,'/lʊk ˈæftər/','Mr. Dale looks after the little church.','戴尔先生照看那座小教堂。','Can you look after my dog this weekend?','这周末你能帮我照看狗吗?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp1','choice','{"stem":"\"The old clock ___ the hours day and night.\"(客观事实、反复发生)","options":["has struck","struck","strikes","is striking"],"answer_index":2,"stem_cn":"那座老钟日夜报时。","explanation_cn":"钟日夜报时,是反复发生、一直如此的客观事实,用一般现在时。✓ The clock strikes the hours. ✗ is striking:不是强调“此刻正在敲”;✗ struck:那是过去;✗ has struck:这里讲经常性的事，不用现在完成。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp1','choice','{"stem":"\"Everyone in town ___ its slow, heavy sound.\"(大家都知道:客观事实)","options":["knows","knew","is knowing","has known"],"answer_index":0,"stem_cn":"镇上每个人都熟悉它那沉沉的钟声。","explanation_cn":"“镇上人人都熟悉这钟声”是一直如此的事实,用一般现在时;know 一般不用进行时。✓ Everyone knows its sound. ✗ is knowing:know 不用进行;✗ knew:那是过去;✗ has known:这里讲的是经常性的事实。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp1','choice','{"stem":"\"The town ___ money for the clock every spring.\"(每年春天:反复的习惯)","options":["raised","is raising","raises","has raised"],"answer_index":2,"stem_cn":"镇上每年春天都为这钟筹钱。","explanation_cn":"“每年春天筹钱”是每年反复的习惯,用一般现在时。✓ The town raises money every spring. ✗ is raising:不是“此刻正在筹”;✗ raised / has raised:时态不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp1','choice','{"stem":"\"Mr. Dale ___ up to the tower almost every night.\"(almost every night:习惯)","options":["comes","is coming","has come","came"],"answer_index":0,"stem_cn":"戴尔先生几乎每晚都上钟楼。","explanation_cn":"almost every night(几乎每晚)是反复的习惯,用一般现在时。✓ Mr. Dale comes up almost every night. ✗ is coming:讲习惯不用进行;✗ came / has come:时态不对。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp2','choice','{"stem":"\"Look — a small light ___ inside the tower right now!\"(right now:此刻正在进行)","options":["has moved","moved","is moving","moves"],"answer_index":2,"stem_cn":"看——此刻钟楼里有一点小灯在动!","explanation_cn":"right now(此刻)那盏小灯正在动,是眼前正在发生的事,用现在进行时。✓ A light is moving right now. ✗ moves:那是讲习惯;✗ moved / has moved:时态不对。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp2','choice','{"stem":"\"Someone ___ up there in the dark at this moment.\"(at this moment:此刻)","options":["is working","has worked","works","worked"],"answer_index":0,"stem_cn":"此刻有人在上面的黑暗里忙活。","explanation_cn":"at this moment(此刻)有人正在上面忙,是眼前进行的动作,用现在进行时。✓ Someone is working now. ✗ works:讲习惯才用;✗ worked / has worked:时态不对。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp2','choice','{"stem":"\"''Why ___ you working up here so late?'' I ask.\"(此刻正在做:现在进行的疑问)","options":["did","are","have","do"],"answer_index":1,"stem_cn":"“你这么晚在上面忙什么?”我问。","explanation_cn":"“你这么晚正在上面忙什么”问的是此刻正在进行的动作,现在进行时的疑问用 are + doing,主语 you 配 are。✓ Why are you working up here? ✗ do / did / have:都不能和后面的 working 搭成“正在做”的问句。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp2','choice','{"stem":"\"These days something new ___ in our quiet town.\"(these days:这一阵临时在发生)","options":["has happened","happens","is happening","happened"],"answer_index":2,"stem_cn":"这一阵,我们安静的小镇上有件新鲜事在发生。","explanation_cn":"these days(这一阵)有件新鲜事在发生,是这段时间临时、正在展开的情况,用现在进行时。✓ Something new is happening these days. ✗ happens:讲经常性;✗ happened / has happened:时态不对。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp3','choice','{"stem":"\"My little brother ___ my things without asking — it''s so annoying!\"(老是……,带抱怨:always + 现在进行)","options":["is always take","is always taking","always is taking","always taking"],"answer_index":1,"stem_cn":"我弟弟老是不打招呼就拿我的东西——真烦人!","explanation_cn":"“老是不打招呼就拿我东西——真烦人”,always + 现在进行表示反复发生、还带点抱怨,固定用 is always + doing。✓ He is always taking my things. ✗ is always take(缺 -ing)、✗ always taking(缺 is)、✗ always is taking(语序乱)都不成立。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp3','choice','{"stem":"\"Grandpa ___ on something in the garage; he can never sit still.\"(老是在鼓捣:always + 现在进行)","options":["is always work","always working","work always is","is always working"],"answer_index":3,"stem_cn":"爷爷老是在车库里鼓捣点什么,他一刻也闲不住。","explanation_cn":"“老是在鼓捣点什么、一刻不闲”,always + 现在进行表示反复、带情绪,用 is always + doing。✓ Grandpa is always working on something. ✗ is always work、✗ always working、✗ work always is:形式都不对。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp4','choice','{"stem":"\"I usually walk to work, but today I ___ the bus because it''s raining.\"(today、下雨:临时情况用现在进行)","options":["am taking","took","have taken","take"],"answer_index":0,"stem_cn":"我平时走路上班,但今天下雨,我改坐公交。","explanation_cn":"平时(usually)走路是习惯,但“今天下雨改坐公交”是临时情况,用现在进行时。✓ Today I am taking the bus. ✗ take:那是讲平时习惯;✗ took / have taken:时态不对。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp4','choice','{"stem":"\"Water ___ at 100 degrees — that''s a simple fact.\"(客观规律:一般现在)","options":["is boiling","boiled","boils","has boiled"],"answer_index":2,"stem_cn":"水在100度沸腾——这是个简单的事实。","explanation_cn":"“水在100度沸腾”是永远成立的客观规律,用一般现在时。✓ Water boils at 100 degrees. ✗ is boiling:那是“此刻正在烧开”;✗ boiled / has boiled:时态不对。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp4','choice','{"stem":"\"Be quiet! The baby ___ right now.\"(right now:此刻正在进行)","options":["sleeps","has slept","slept","is sleeping"],"answer_index":3,"stem_cn":"小声点!宝宝正在睡觉。","explanation_cn":"right now(此刻)宝宝正在睡,眼前正在进行的动作,用现在进行时。✓ The baby is sleeping right now. ✗ sleeps:那是讲习惯;✗ slept / has slept:时态不对。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp5','choice','{"stem":"\"She counted the strange strokes ___ surprise.\"(表示“惊讶地”,用哪个介词)","options":["in","with","on","at"],"answer_index":0,"stem_cn":"她惊讶地数着那奇怪的钟响。","explanation_cn":"“惊讶地”这个意思,英语固定说 in surprise,用介词 in。✓ She counted the strokes in surprise. ✗ with / on / at surprise:都不是固定说法。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp5','choice','{"stem":"\"Don''t worry — everything will be fine ___ the end.\"(表示“最后、终于”,用哪个介词)","options":["on","by","in","at"],"answer_index":2,"stem_cn":"别担心,最后一切都会好起来。","explanation_cn":"“最后、终于”这个意思,英语固定说 in the end,用介词 in。✓ Everything will be fine in the end. ✗ at / on / by the end:意思或搭配都不对(at the end 指“在……的末端”)。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp6','choice','{"stem":"\"For our clock, thirteen ___ one.\"(“等于”用哪个词)","options":["divides","breaks","loses","equals"],"answer_index":3,"stem_cn":"对我们这钟来说,十三等于一。","explanation_cn":"“十三等于一”的“等于”是 equal(此处第三人称单数 equals)。✓ thirteen equals one. ✗ breaks 打破;✗ divides 分开;✗ loses 丢失——都不表示“等于”。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp6','choice','{"stem":"\"The town is trying to ___ money to fix the clock.\"(“募集、筹款”用哪个词)","options":["raise","spend","borrow","waste"],"answer_index":0,"stem_cn":"镇上正想筹钱把钟修好。","explanation_cn":"“为修钟筹钱、募集”用 raise（raise money）。✓ raise money to fix the clock. ✗ spend 花掉;✗ waste 浪费;✗ borrow 借入——都不是“募集”。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',5,'am3_l02_gp6','choice','{"stem":"\"I always ___ his voice the moment he speaks.\"(“认出”用哪个词)","options":["sell","forget","invite","recognize"],"answer_index":3,"stem_cn":"他一开口我总能认出他的声音。","explanation_cn":"“一开口就认出他的声音”用 recognize（认出、辨认出）。✓ I recognize his voice. ✗ forget 忘记;✗ invite 邀请;✗ sell 出售——都不是“认出”。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',6,NULL,'choice','{"stem":"美语里\"手电筒\"常说:","options":["flashlight","torch","hand-lamp","night-light"],"answer_index":0,"explanation_cn":"美语里“手电筒”常说 flashlight(英式说 torch);torchlight 指“手电筒发出的光”。✓ I grab a flashlight."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',6,NULL,'choice','{"stem":"equal(动词)的意思是:","options":["减少","分开","打破","等于"],"answer_index":3,"explanation_cn":"equal(动词)= 等于。✓ thirteen equals one 十三等于一。\n顺带记:分开 = divide;打破 = break;减少 = reduce."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',6,NULL,'choice','{"stem":"raise 的意思是:","options":["浪费","花光","募集,筹(款)","借入"],"answer_index":2,"explanation_cn":"raise = 募集、筹(款)。✓ raise money 筹钱。\n顺带记:花光 = spend;借入 = borrow;浪费 = waste."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',6,NULL,'choice','{"stem":"recognize 的意思是:","options":["认出","忘记","邀请","允许"],"answer_index":0,"explanation_cn":"recognize = 认出、辨认出。✓ I recognize him 我认出了他。\n顺带记:忘记 = forget;邀请 = invite;允许 = allow."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',6,NULL,'choice','{"stem":"strike(指钟)的意思是:","options":["停下","敲响,报时","上锁","熄灭"],"answer_index":1,"explanation_cn":"strike(指钟)= 敲响、报时。✓ the clock strikes the hours 钟报时。\n顺带记:熄灭 = put out;停下 = stop;上锁 = lock."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',6,NULL,'choice','{"stem":"\"in surprise\" 的意思是:","options":["高兴地","生气地","小心地","惊讶地"],"answer_index":3,"explanation_cn":"in surprise = 惊讶地(一批要整体记的 in 短语之一)。✓ He looked at me in surprise 他惊讶地看着我。\n顺带记:高兴地 = happily;生气地 = angrily;小心地 = carefully."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',7,NULL,'cloze','{"stem":"第 1 空","context":"Our town clock is famous for one strange habit. Every night at one o''clock it ___1___ thirteen times. Right now a small light ___2___ inside the tower, because someone ___3___ to fix the old bell. Most people just smile and say that, for this clock, thirteen ___4___ one.","blank_no":1,"options":["is striking","strikes","struck","has struck"],"answer_index":1,"explanation_cn":"Every night at one o''clock(每晚一点)是反复发生的习惯,用一般现在时。✓ it strikes thirteen times."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',7,NULL,'cloze','{"stem":"第 2 空","context":"Our town clock is famous for one strange habit. Every night at one o''clock it ___1___ thirteen times. Right now a small light ___2___ inside the tower, because someone ___3___ to fix the old bell. Most people just smile and say that, for this clock, thirteen ___4___ one.","blank_no":2,"options":["is moving","moves","moved","has moved"],"answer_index":0,"explanation_cn":"Right now(此刻)那盏小灯正在动,眼前正在进行,用现在进行时。✓ a small light is moving."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',7,NULL,'cloze','{"stem":"第 3 空","context":"Our town clock is famous for one strange habit. Every night at one o''clock it ___1___ thirteen times. Right now a small light ___2___ inside the tower, because someone ___3___ to fix the old bell. Most people just smile and say that, for this clock, thirteen ___4___ one.","blank_no":3,"options":["tries","is trying","tried","has tried"],"answer_index":1,"explanation_cn":"“有人正在修钟”是此刻正在做的动作,用现在进行时。✓ someone is trying to fix the bell."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',7,NULL,'cloze','{"stem":"第 4 空","context":"Our town clock is famous for one strange habit. Every night at one o''clock it ___1___ thirteen times. Right now a small light ___2___ inside the tower, because someone ___3___ to fix the old bell. Most people just smile and say that, for this clock, thirteen ___4___ one.","blank_no":4,"options":["equals","is equaling","equaled","has equaled"],"answer_index":0,"explanation_cn":"“十三等于一”是对这钟一直成立的说法,用一般现在时。✓ thirteen equals one."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',8,NULL,'choice','{"stem":"What does the town clock do at one o''clock?","options":["It strikes thirteen times","It stops completely","It plays music","It rings once softly"],"answer_index":0,"explanation_cn":"课文说 at one o''clock the clock strikes thirteen times——一点时它敲十三下。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',8,NULL,'choice','{"stem":"Who is fixing the bell at night?","options":["A police officer","The town mayor","Old Mr. Dale","A young tourist"],"answer_index":2,"explanation_cn":"课文说 By the torchlight I recognize old Mr. Dale… ''I am trying to fix the bell''——半夜修钟的是老戴尔先生。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',8,NULL,'choice','{"stem":"How does the town feel about the clock in the end?","options":["They ignore Mr. Dale","They smile and accept it","They tear it down","They are furious"],"answer_index":1,"explanation_cn":"课文说 the town just smiles and calls it one——最后全镇一笑,把十三下当成一点接受了。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',9,NULL,'choice','{"stem":"你想说\"我平时喝茶,但今天在喝咖啡\"(习惯 vs 此刻正在进行):","options":["I am usually drink tea, but today I drinking coffee.","I usually drink tea, but today I am drinking coffee.","I usually am drinking tea, but today I drink coffee.","I usually drinking tea, but today I am drink coffee."],"answer_index":1,"explanation_cn":"usually(平时)讲习惯用一般现在 drink;today(今天)这一临时情况用现在进行 am drinking。✓ I usually drink tea, but today I am drinking coffee. 场合:讲“平时……,但今天正在……”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',9,NULL,'choice','{"stem":"你想说\"他老是丢钥匙\"(带抱怨:always + 现在进行):","options":["He is always losing his keys.","He is always lose his keys.","He always is losing his keys.","He always losing his keys."],"answer_index":0,"explanation_cn":"“老是丢钥匙”带抱怨,用 always + 现在进行,固定形式 is always + doing。✓ He is always losing his keys. 场合:抱怨某人反复做某件烦人的事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',9,NULL,'choice','{"stem":"你想说\"她惊讶地看着那只钟\"(固定搭配 in surprise):","options":["She looks at the clock by surprise.","She looks at the clock on surprise.","She looks at the clock in surprise.","She looks at the clock at surprise."],"answer_index":2,"explanation_cn":"“惊讶地”固定说 in surprise,用介词 in。✓ She looks at the clock in surprise. 场合:表示某人“惊讶地”做某事。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',10,NULL,'choice','{"stem":"recognize 的意思是:","options":["出售","认出,辨认出","忘记","邀请"],"answer_index":1,"explanation_cn":"recognize = 认出、辨认出。✓ I recognize old Mr. Dale 我认出了老戴尔先生。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',10,NULL,'choice','{"stem":"raise(此处)的意思是:","options":["募集,筹(款)","浪费","花掉","借入"],"answer_index":0,"explanation_cn":"raise（此处）= 募集、筹(款)。✓ raise money to fix the clock 筹钱修钟。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',10,NULL,'choice','{"stem":"\"Listen! The baby ___ right now.\"(此刻正在进行)","options":["cries","is crying","has cried","cried"],"answer_index":1,"stem_cn":"听!宝宝正在哭。","explanation_cn":"Listen!(听!)提示眼前正在发生,宝宝此刻正在哭,用现在进行时。✓ The baby is crying right now. ✗ cries / cried / has cried:时态不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',10,NULL,'choice','{"stem":"\"The clock ___ the hours every single day.\"(客观事实、反复)","options":["strikes","is striking","has struck","struck"],"answer_index":0,"stem_cn":"这钟每天都报时。","explanation_cn":"every single day(每天)是反复发生的客观事实,用一般现在时。✓ The clock strikes the hours every day. ✗ is striking / struck / has struck:时态不对。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',10,NULL,'choice','{"stem":"\"in a hurry\" 的意思是:","options":["很悠闲","在睡觉","匆忙","在休息"],"answer_index":2,"explanation_cn":"in a hurry = 匆忙、急急忙忙(一批要整体记的 in 短语之一)。✓ He is always in a hurry 他总是急匆匆的。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',10,NULL,'choice','{"stem":"\"in the end\" 的意思是:","options":["在中间","最后,终于","一开始","偶尔"],"answer_index":1,"explanation_cn":"in the end = 最后、终于。✓ In the end, the town smiles about it 最后全镇一笑了之。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',10,NULL,'choice','{"stem":"What is strange about the town clock?","options":["It has completely disappeared","It never makes any sound","It shows the wrong date","At one o''clock it strikes thirteen times"],"answer_index":3,"passage":"In our town, the old clock on the town hall is always causing trouble. It stands high above Main Street and strikes the hours day and night. Everyone knows its slow, heavy sound, and the town keeps trying to raise money to fix it. The strange thing is this: at one o''clock the clock strikes thirteen times. It is really one o''clock, but for our clock, thirteen equals one. Most nights I lie in bed and count the strokes in surprise. These days something new is happening. Every night a small light is moving inside the tower, and someone is working up there in the dark. Tonight I finally grab a flashlight and cross the empty square. By the torchlight I recognize old Mr. Dale, who looks after the little church next door and often helps the vicar there. ''What are you doing up here so late?'' I ask. ''I am trying to fix the bell,'' he says quietly. ''I come up here almost every night now. I hate to see the whole town in trouble over one old clock.'' Mr. Dale is not a young man, and he is always working on something, but he never gives up. So far the clock still strikes thirteen, and the town just smiles and calls it one.","explanation_cn":"课文说 at one o''clock the clock strikes thirteen times——一点时它敲十三下,这就是奇怪之处。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',10,NULL,'choice','{"stem":"Who does the narrator recognize in the tower?","options":["Old Mr. Dale","A young girl","A stranger from the city","The town mayor"],"answer_index":0,"passage":"In our town, the old clock on the town hall is always causing trouble. It stands high above Main Street and strikes the hours day and night. Everyone knows its slow, heavy sound, and the town keeps trying to raise money to fix it. The strange thing is this: at one o''clock the clock strikes thirteen times. It is really one o''clock, but for our clock, thirteen equals one. Most nights I lie in bed and count the strokes in surprise. These days something new is happening. Every night a small light is moving inside the tower, and someone is working up there in the dark. Tonight I finally grab a flashlight and cross the empty square. By the torchlight I recognize old Mr. Dale, who looks after the little church next door and often helps the vicar there. ''What are you doing up here so late?'' I ask. ''I am trying to fix the bell,'' he says quietly. ''I come up here almost every night now. I hate to see the whole town in trouble over one old clock.'' Mr. Dale is not a young man, and he is always working on something, but he never gives up. So far the clock still strikes thirteen, and the town just smiles and calls it one.","explanation_cn":"课文说 By the torchlight I recognize old Mr. Dale——叙述者在钟楼里认出的是老戴尔先生。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',10,NULL,'choice','{"stem":"Why does Mr. Dale go up to the tower?","options":["To ring the bell for fun","To sleep up there","To fix the old bell","To hide from the town"],"answer_index":2,"audio":"In our town, the old clock on the town hall is always causing trouble. It stands high above Main Street and strikes the hours day and night. Everyone knows its slow, heavy sound, and the town keeps trying to raise money to fix it. The strange thing is this: at one o''clock the clock strikes thirteen times. It is really one o''clock, but for our clock, thirteen equals one. Most nights I lie in bed and count the strokes in surprise. These days something new is happening. Every night a small light is moving inside the tower, and someone is working up there in the dark. Tonight I finally grab a flashlight and cross the empty square. By the torchlight I recognize old Mr. Dale, who looks after the little church next door and often helps the vicar there. ''What are you doing up here so late?'' I ask. ''I am trying to fix the bell,'' he says quietly. ''I come up here almost every night now. I hate to see the whole town in trouble over one old clock.'' Mr. Dale is not a young man, and he is always working on something, but he never gives up. So far the clock still strikes thirteen, and the town just smiles and calls it one.","explanation_cn":"课文说 ''I am trying to fix the bell''——戴尔先生半夜上钟楼是为了修那口老钟。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l02',10,NULL,'choice','{"stem":"What does the town finally do about the clock?","options":["They fix it perfectly","They accept it and smile","They sell it to a museum","They remove it"],"answer_index":1,"audio":"In our town, the old clock on the town hall is always causing trouble. It stands high above Main Street and strikes the hours day and night. Everyone knows its slow, heavy sound, and the town keeps trying to raise money to fix it. The strange thing is this: at one o''clock the clock strikes thirteen times. It is really one o''clock, but for our clock, thirteen equals one. Most nights I lie in bed and count the strokes in surprise. These days something new is happening. Every night a small light is moving inside the tower, and someone is working up there in the dark. Tonight I finally grab a flashlight and cross the empty square. By the torchlight I recognize old Mr. Dale, who looks after the little church next door and often helps the vicar there. ''What are you doing up here so late?'' I ask. ''I am trying to fix the bell,'' he says quietly. ''I come up here almost every night now. I hate to see the whole town in trouble over one old clock.'' Mr. Dale is not a young man, and he is always working on something, but he never gives up. So far the clock still strikes thirteen, and the town just smiles and calls it one.","explanation_cn":"课文说 the town just smiles and calls it one——全镇最后接受了它,一笑置之。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l03',3,1,3,'The Unknown Goddess','无名女神','一般过去时讲“发生了什么”,重点在不规则动词的过去式(find→found、dig→dug、stand→stood、begin→began、come→came、feel→felt、wear→wore、sweep→swept…),外加易混词 happen(to be)碰巧、美式 story(楼层,与''故事''同形;英式 storey)、worship(崇拜)↔warship(军舰)(原创承载 NCE3 L3 考点·美国考古队复原古代女神像)','几年前,一支美国考古队在海边一处岩石岬角上勘探一座古城遗址。那座古城当年一定很繁荣,因为它曾有很高的文明水平。考古学家发现了宽阔的街道,街道下面挖出了旧排水系统的陶管。常有三层高的石屋沿路而立。在一座残破神殿最神圣的房间里,工人们找到了许多小雕像的碎片。每尊都是一位女神,当年都上过彩。考古队把碎片带回实验室,开始慢慢拼合。有一尊格外费解:身体来自很古老的遗物,头却碰巧来自晚得多的古典时代——想必古代有人捡到这颗头,认出它的价值,小心保存了下来。等到终于复原,考古队惊讶地发现:这位女神看上去像个非常现代的女子。她约三英尺高,双手叉在臀部,穿一条拖地长裙。尽管年代久远,她却真的很优雅。可到目前为止,谁也查不出她的身份。','{"q":"Listen and answer — What did the American team find in the sacred room?","options":["Fragments of many goddess statues","A chest of gold coins","A living animal","A pile of old books"],"answer_index":0}'::jsonb,'{"title":"讲“发生了什么”:一般过去时 & 不规则动词过去式","intro":"讲过去发生、已经完成的事,用一般过去时。规则动词直接加 -ed(explore→explored、enjoy→enjoyed);但很多常用动词是不规则的,必须一个个记牢:find→found、dig→dug、stand→stood、begin→began、come→came、feel→felt、wear→wore、sweep→swept、keep→kept。另外记三组易混:①happen to be = 碰巧是(By chance);②美语里“楼层”拼 story(复数 stories),和“故事”同形,英式才拼 storey;③worship(崇拜、礼拜)别和 warship(军舰)搞混。","table":{"headers":["动词原形","过去式(不规则)","例子"],"rows":[["find / dig / stand","found / dug / stood","they found the fragments; they dug up pipes"],["begin / come","began / came","the work began; the head came from later remains"],["feel / wear / sweep","felt / wore / swept","they felt amazed; she wore a long skirt"],["happen (to be)","happened (to be)","the head happened to be much older"]]},"specialRules":[{"rule":"不规则动词过去式没有规律,只能背:begin→began(不是 beginned)、come→came(不是 comed)、feel→felt(不是 feeled)。注意别把过去分词当过去式:begun/worn 是过去分词。","mark":"begin→began / feel→felt"},{"rule":"美语里“楼层”和“故事”都拼 story(a three-story house / an old story);英式把“楼层”拼作 storey 以区分。本课已按美语写 stories。","mark":"story / storey"},{"rule":"worship /ˈwɜːrʃɪp/ 崇拜、礼拜;warship /ˈwɔːrʃɪp/ 军舰。拼写、意思都不同,别弄混。","mark":"worship / warship"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l03',1,NULL,'A few years ago, an American team explored an ancient site on a rocky promontory high above the sea. The old city there must have been prosperous, for it once enjoyed a high level of civilization.','几年前,一支美国考古队在海边一处岩石岬角上勘探一座古城遗址。那座古城当年一定很繁荣,因为它曾有很高的文明水平。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l03',2,NULL,'The archaeologists found wide streets, and beneath them they dug up clay pipes from an old drainage system. Houses, often three stories high, stood along the road.','考古学家发现了宽阔的街道,街道下面挖出了旧排水系统的陶管。常有三层高的石屋沿路而立。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l03',3,NULL,'In the most sacred room of a ruined temple, once a busy place of worship, the workers found the fragments of many small statues. Each one showed a goddess, and each had once been painted in bright colors.','在一座残破神殿——从前热闹的礼拜之地——最神圣的房间里,工人们找到了许多小雕像的碎片。每尊都是一位女神,当年都上过彩。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l03',4,NULL,'One statue puzzled everyone. Its body came from very old remains, but its head happened to be from a much later, classical time. Someone in ancient days must have found the head and kept it with great care.','有一尊格外费解:身体来自很古老的遗物,头却碰巧来自晚得多的古典时代。想必古代有人捡到这颗头,小心保存了下来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l03',5,NULL,'When the archaeologists finally reconstructed the figure, they felt amazed. The goddess looked like a very modern woman. She wore a full-length skirt that swept the floor, and she was truly graceful. So far, no one has been able to discover her identity.','等到终于复原,考古队惊讶地发现:这位女神看上去像个非常现代的女子。她穿一条拖地长裙,真的很优雅。可到目前为止,谁也查不出她的身份。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
