INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l03','story','storey','楼层;美语 story(复数 stories,与''故事''同形),英式 storey') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l03','elevator','lift','电梯;美语 elevator,英式 lift') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l03','apartment','flat','公寓;美语 apartment,英式 flat') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l03','downtown','town centre','市中心;美语 downtown,英式 town centre') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l03','happen to be','',NULL,'/ˈhæpən tuː biː/','Its head happened to be from a later time.','那颗头碰巧来自较晚的时代。','I happen to know the answer.','我碰巧知道答案。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l03','put together','',NULL,'/pʊt təˈɡeðər/','They put the broken pieces together.','他们把碎片拼合起来。','It took hours to put the model together.','拼好这个模型花了好几个小时。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l03','a high level of','',NULL,'/ə haɪ ˈlevl əv/','The city enjoyed a high level of civilization.','这座城市曾有很高的文明水平。','The team showed a high level of skill.','这支队伍展现了很高的水平。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l03','so far','',NULL,'/soʊ fɑːr/','So far, no one has discovered her identity.','到目前为止,没人查出她的身份。','So far, everything is going well.','到目前为止,一切都很顺利。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp1','choice','{"stem":"\"A few years ago, an American team ___ an ancient site by the sea.\"(过去发生:一般过去时)","options":["is exploring","explores","has explored","explored"],"answer_index":3,"stem_cn":"几年前,一支美国考古队勘探了海边一处古城遗址。","explanation_cn":"“几年前勘探了遗址”是过去发生、已完成的事,用一般过去时;explore 是规则动词,加 -ed。✓ the team explored an ancient site. ✗ explores / is exploring:不是现在;✗ has explored:这里有明确的过去时间(a few years ago),不用现在完成。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp1','choice','{"stem":"\"The old city once ___ a high level of civilization.\"(过去:enjoy 的过去式)","options":["is enjoying","has enjoyed","enjoyed","enjoys"],"answer_index":2,"stem_cn":"那座古城曾有很高的文明水平。","explanation_cn":"“曾拥有很高的文明水平”讲过去,enjoy 加 -ed。✓ the city enjoyed a high level of civilization. ✗ enjoys / is enjoying / has enjoyed:时态不对。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp1','choice','{"stem":"\"Each little statue ___ a goddess.\"(过去:show 的过去式)","options":["shows","has shown","is showing","showed"],"answer_index":3,"stem_cn":"每一尊小雕像都是一位女神。","explanation_cn":"“每尊都是一位女神”讲过去,show 的过去式 showed。✓ each statue showed a goddess. ✗ shows / is showing / has shown:时态不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp2','choice','{"stem":"\"Beneath the streets, the workers ___ up old clay pipes.\"(dig 的过去式)","options":["digs","digged","dug","dig"],"answer_index":2,"stem_cn":"在街道下面,工人们挖出了旧陶管。","explanation_cn":"dig(挖)是不规则动词,过去式是 dug(不是 digged)。✓ the workers dug up old pipes. ✗ digged:不存在;✗ digs / dig:不是过去式。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp2','choice','{"stem":"\"In the sacred room they ___ many broken pieces.\"(find 的过去式)","options":["found","finded","find","finds"],"answer_index":0,"stem_cn":"在那神圣的房间里,他们发现了许多碎片。","explanation_cn":"find(找到)的过去式是不规则的 found(不是 finded)。✓ they found many pieces. ✗ finded:不存在;✗ finds / find:不是过去式。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp2','choice','{"stem":"\"Tall stone houses ___ along the narrow road.\"(stand 的过去式)","options":["standed","stands","stand","stood"],"answer_index":3,"stem_cn":"高高的石屋沿着狭窄的路排列。","explanation_cn":"stand(立着)的过去式是不规则的 stood(不是 standed)。✓ the houses stood along the road. ✗ standed:不存在;✗ stands / stand:不是过去式。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp2','choice','{"stem":"\"The team ___ the slow work of putting the pieces together.\"(begin 的过去式,别用过去分词)","options":["begins","beginned","began","begun"],"answer_index":2,"stem_cn":"考古队开始了把碎片拼合的缓慢工作。","explanation_cn":"begin 的过去式是 began;begun 是过去分词,不能单独作过去式。✓ the team began the work. ✗ begun:那是过去分词;✗ begins / beginned:都不对。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp3','choice','{"stem":"\"The body ___ from very old remains.\"(come 的过去式)","options":["came","comed","comes","come"],"answer_index":0,"stem_cn":"这身体来自很古老的遗物。","explanation_cn":"come 的过去式是不规则的 came(不是 comed)。✓ the body came from old remains. ✗ comed:不存在;✗ comes / come:不是过去式。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp3','choice','{"stem":"\"When they saw the result, they ___ amazed.\"(feel 的过去式)","options":["feels","feel","feeled","felt"],"answer_index":3,"stem_cn":"他们一看到结果就感到惊讶。","explanation_cn":"feel 的过去式是不规则的 felt(不是 feeled)。✓ they felt amazed. ✗ feeled:不存在;✗ feels / feel:不是过去式。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp3','choice','{"stem":"\"She ___ a full-length skirt that swept the floor.\"(wear 的过去式,别用过去分词)","options":["wears","weared","wore","worn"],"answer_index":2,"stem_cn":"她穿着一条拖到地面的长裙。","explanation_cn":"wear 的过去式是 wore;worn 是过去分词,不能单独作过去式。✓ she wore a long skirt. ✗ worn:那是过去分词;✗ wears / weared:都不对。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp4','choice','{"stem":"\"Its head ___ to be from a much later time.\"(碰巧是:happen to be,过去)","options":["happened","is happening","happens","has happened"],"answer_index":0,"stem_cn":"它的头碰巧来自晚得多的时代。","explanation_cn":"happen to be = 碰巧是;讲过去用过去式 happened。✓ its head happened to be much older. ✗ happens / is happening / has happened:时态不对。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp4','choice','{"stem":"\"It ___ that the head was far more precious than the body.\"(碰巧发生:固定句式 It ... that…,过去时)","options":["happens","was happening","happened","has happened"],"answer_index":2,"stem_cn":"碰巧,那颗头比身体珍贵得多。","explanation_cn":"it happened that… = 碰巧……;讲过去用过去式 happened。✓ It happened that the head was more precious. ✗ happens / was happening / has happened:时态不对。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp5','choice','{"stem":"美语里,\"楼层\"和\"故事\"拼法相同,都拼作:","options":["storey","story","stall","stair"],"answer_index":1,"explanation_cn":"美语里“楼层”和“故事”拼法相同,都拼 story(a three-story house / an old story);英式才把“楼层”拼作 storey。✓ story. ✗ storey 是英式拼法;✗ stall(货摊)/ stair(台阶)意思不对。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp5','choice','{"stem":"worship 的意思是:","options":["碎片","楼层","崇拜,礼拜","军舰"],"answer_index":2,"explanation_cn":"worship = 崇拜、礼拜(a place of worship 礼拜的地方)。✓ 崇拜,礼拜。✗ 军舰是 warship(别混);✗ 楼层 = story;✗ 碎片 = fragment。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp5','choice','{"stem":"warship 的意思是:","options":["海角","军舰","女神","崇拜"],"answer_index":1,"explanation_cn":"warship = 军舰(和 worship 崇拜拼写、意思都不同)。✓ 军舰。✗ 崇拜 = worship;✗ 海角 = promontory;✗ 女神 = goddess。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp6','choice','{"stem":"\"The broken pieces of the statues are called ___.\"(碎片用哪个词)","options":["pipes","skirts","streets","fragments"],"answer_index":3,"stem_cn":"雕像的碎块叫做 fragments(碎片)。","explanation_cn":"雕像摔碎后的小块叫 fragments(碎片)。✓ the fragments of the statues. ✗ streets 街道;✗ pipes 管道;✗ skirts 裙子——都不是“碎片”。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp6','choice','{"stem":"\"To put the broken pieces back together is to ___ the statue.\"(修复、重建用哪个词)","options":["reconstruct","destroy","paint","bury"],"answer_index":0,"stem_cn":"把碎片拼合起来就是复原这尊雕像。","explanation_cn":"把碎片重新拼合、恢复原样,用 reconstruct(修复、重建)。✓ reconstruct the statue. ✗ destroy 摧毁;✗ paint 上色;✗ bury 埋葬——意思相反或无关。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',5,'am3_l03_gp6','choice','{"stem":"\"No one knows who she is; they cannot discover her ___.\"(身份用哪个词)","options":["drainage","identity","civilization","promontory"],"answer_index":1,"stem_cn":"谁也不知道她是谁,查不出她的身份。","explanation_cn":"“查不出她是谁”指查不出她的身份,用 identity。✓ discover her identity. ✗ drainage 排水;✗ promontory 海角;✗ civilization 文明——都不是“身份”。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',6,NULL,'choice','{"stem":"美语里\"楼层\"拼作(和\"故事\"同形):","options":["level","story","stair","storey"],"answer_index":1,"explanation_cn":"美语里“楼层”和“故事”都拼 story(英式“楼层”拼 storey)。✓ a three-story house 三层楼的房子。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',6,NULL,'choice','{"stem":"goddess 的意思是:","options":["女神","海角","军舰","碎片"],"answer_index":0,"explanation_cn":"goddess = 女神。✓ each statue showed a goddess 每尊像都是一位女神。\n顺带记:军舰 = warship;海角 = promontory;碎片 = fragment."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',6,NULL,'choice','{"stem":"archaeologist 的意思是:","options":["历史老师","探险家","建筑师","考古学家"],"answer_index":3,"explanation_cn":"archaeologist = 考古学家。✓ the archaeologists explored the site 考古学家勘探了遗址。\n顺带记:建筑师 = architect;探险家 = explorer;历史老师 = history teacher."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',6,NULL,'choice','{"stem":"sacred 的意思是:","options":["现代的","昂贵的","神圣的","破旧的"],"answer_index":2,"explanation_cn":"sacred = 神圣的、宗教的。✓ the most sacred room 最神圣的房间。\n顺带记:破旧的 = shabby;昂贵的 = expensive;现代的 = modern."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',6,NULL,'choice','{"stem":"graceful 的意思是:","options":["优雅的","笨拙的","生气的","古老的"],"answer_index":0,"explanation_cn":"graceful = 优雅的。✓ she was truly graceful 她真的很优雅。\n顺带记:笨拙的 = clumsy;生气的 = angry;古老的 = ancient."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',6,NULL,'choice','{"stem":"\"happen to be\" 的意思是:","options":["拒绝是","假装是","必须是","碰巧是"],"answer_index":3,"explanation_cn":"happen to be = 碰巧是(表示纯属巧合)。✓ Its head happened to be much older 它的头碰巧老得多。\n顺带记:必须是 = must be;假装是 = pretend to be;拒绝 = refuse."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',7,NULL,'cloze','{"stem":"第 1 空","context":"A few years ago, an American team ___1___ an ancient temple by the sea. In the sacred room they ___2___ the fragments of many small statues. One head ___3___ to be from a much later time. When the team finally put the pieces together, they ___4___ amazed to see a very modern-looking goddess.","blank_no":1,"options":["explored","explores","was exploring","has explored"],"answer_index":0,"explanation_cn":"“几年前勘探了神殿”是过去发生的事,用一般过去时。✓ an American team explored an ancient temple."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',7,NULL,'cloze','{"stem":"第 2 空","context":"A few years ago, an American team ___1___ an ancient temple by the sea. In the sacred room they ___2___ the fragments of many small statues. One head ___3___ to be from a much later time. When the team finally put the pieces together, they ___4___ amazed to see a very modern-looking goddess.","blank_no":2,"options":["find","found","are finding","have found"],"answer_index":1,"explanation_cn":"find 的过去式是 found;“他们发现了碎片”讲过去。✓ they found the fragments."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',7,NULL,'cloze','{"stem":"第 3 空","context":"A few years ago, an American team ___1___ an ancient temple by the sea. In the sacred room they ___2___ the fragments of many small statues. One head ___3___ to be from a much later time. When the team finally put the pieces together, they ___4___ amazed to see a very modern-looking goddess.","blank_no":3,"options":["happens","happened","is happening","has happened"],"answer_index":1,"explanation_cn":"happen to be = 碰巧是,讲过去用 happened。✓ one head happened to be from a later time."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',7,NULL,'cloze','{"stem":"第 4 空","context":"A few years ago, an American team ___1___ an ancient temple by the sea. In the sacred room they ___2___ the fragments of many small statues. One head ___3___ to be from a much later time. When the team finally put the pieces together, they ___4___ amazed to see a very modern-looking goddess.","blank_no":4,"options":["felt","feel","are feeling","have felt"],"answer_index":0,"explanation_cn":"feel 的过去式是 felt;“他们感到惊讶”讲过去。✓ they felt amazed."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',8,NULL,'choice','{"stem":"Where did the American team make their discovery?","options":["Deep inside a cave","In a modern city downtown","On a small farm","At an ancient site on a promontory by the sea"],"answer_index":3,"explanation_cn":"课文说 an American team explored an ancient site on a rocky promontory high above the sea——发现地点是海边岬角上的古城遗址。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',8,NULL,'choice','{"stem":"What did the archaeologists find in the sacred room?","options":["Fragments of many small goddess statues","A pile of old books","A living animal","A chest of gold coins"],"answer_index":0,"explanation_cn":"课文说 the workers found the fragments of many small statues… each one showed a goddess——他们发现的是许多女神小像的碎片。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',8,NULL,'choice','{"stem":"What surprised the team about the reconstructed goddess?","options":["She was extremely tiny","She looked like a very modern woman","She had no head at all","She was made of pure gold"],"answer_index":1,"explanation_cn":"课文说 the goddess looked like a very modern woman——复原后大家惊讶地发现她像个现代女子。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',9,NULL,'choice','{"stem":"你想说\"昨天我把这些照片拼在了一起\"(一般过去 + put 的过去式仍是 put):","options":["Yesterday I put these photos together.","Yesterday I am putting these photos together.","Yesterday I have put these photos together.","Yesterday I putted these photos together."],"answer_index":0,"explanation_cn":"put 的过去式仍是 put(形式不变);“昨天拼好了”讲过去。✓ Yesterday I put these photos together. 场合:讲昨天完成的一件事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',9,NULL,'choice','{"stem":"你想说\"我碰巧认识那位考古学家\"(happen to do):","options":["I happened to knowing that archaeologist.","I happen knowing that archaeologist.","I happen to know that archaeologist.","I am happen to know that archaeologist."],"answer_index":2,"explanation_cn":"happen to do = 碰巧做某事,后面接动词原形。✓ I happen to know that archaeologist. 场合:说自己“碰巧、恰好”认识/知道某人某事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',9,NULL,'choice','{"stem":"你想说\"他们惊讶地发现她看起来很现代\"(feel 的过去式 felt):","options":["They were felt amazed to find that she looked modern.","They felt amazed to found that she looked modern.","They feeled amazed to find that she looked modern.","They felt amazed to find that she looked modern."],"answer_index":3,"explanation_cn":"feel 的过去式是 felt,后面 to find 用动词原形。✓ They felt amazed to find that she looked modern. 场合:讲过去某人惊讶地发现某事。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',10,NULL,'choice','{"stem":"identity 的意思是:","options":["排水","军舰","楼层","身份"],"answer_index":3,"explanation_cn":"identity = 身份。✓ discover her identity 查出她的身份。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',10,NULL,'choice','{"stem":"reconstruct 的意思是:","options":["修复,重建","出售","摧毁","埋葬"],"answer_index":0,"explanation_cn":"reconstruct = 修复、重建(把碎片拼回原样)。✓ reconstruct the figure 复原这尊像。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',10,NULL,'choice','{"stem":"\"Yesterday the workers ___ up old pipes under the street.\"(dig 的过去式)","options":["dig","dug","digs","digged"],"answer_index":1,"stem_cn":"昨天工人们在街道下面挖出了旧管道。","explanation_cn":"dig 的过去式是不规则的 dug。✓ the workers dug up old pipes. ✗ digged / digs / dig:都不是正确的过去式。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',10,NULL,'choice','{"stem":"\"When they saw it, they ___ amazed.\"(feel 的过去式)","options":["feeled","feels","feel","felt"],"answer_index":3,"stem_cn":"他们一看见就感到惊讶。","explanation_cn":"feel 的过去式是不规则的 felt。✓ they felt amazed. ✗ feeled / feels / feel:都不是正确的过去式。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',10,NULL,'choice','{"stem":"\"happen to be\" 的意思是:","options":["必须是","假装是","碰巧是","拒绝是"],"answer_index":2,"explanation_cn":"happen to be = 碰巧是。✓ Its head happened to be much older 它的头碰巧老得多。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',10,NULL,'choice','{"stem":"\"so far\" 的意思是:","options":["到目前为止","一开始","从此以后","很远地"],"answer_index":0,"explanation_cn":"so far = 到目前为止。✓ So far, no one has discovered her identity 到目前为止没人查出她的身份。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',10,NULL,'choice','{"stem":"Why does the team think the old city was prosperous?","options":["It had a busy airport","It was full of gold statues","It had tall glass towers","It had a high level of civilization, with stone houses and drainage"],"answer_index":3,"passage":"A few years ago, an American team explored an ancient site on a rocky promontory high above the sea. The old city there must have been prosperous, for it once enjoyed a high level of civilization. The archaeologists found wide streets, and beneath them they dug up clay pipes from an old drainage system. Houses, often three stories high, stood along the road. In the most sacred room of a ruined temple, once a busy place of worship, the workers found the fragments of many small statues. Each one showed a goddess, and each had once been painted in bright colors. The team carried the pieces back to the lab and began the slow work of putting them together. One statue puzzled everyone. Its body came from very old remains, but its head happened to be from a much later, classical time. Someone in ancient days must have found the head, recognized its value, and kept it with great care. When the archaeologists finally reconstructed the figure, they felt amazed. The goddess looked like a very modern woman. She stood about three feet high, her hands rested on her hips, and she wore a full-length skirt that swept the floor. Despite her great age, she was truly graceful. So far, however, no one has been able to discover her identity.","explanation_cn":"课文说 the city must have been prosperous, for it once enjoyed a high level of civilization——石屋、排水系统都说明文明水平高,所以判断它曾经繁荣。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',10,NULL,'choice','{"stem":"What is strange about the reconstructed goddess?","options":["She is taller than a house","She looks like a very modern woman","She is made of ice","She has three heads"],"answer_index":1,"passage":"A few years ago, an American team explored an ancient site on a rocky promontory high above the sea. The old city there must have been prosperous, for it once enjoyed a high level of civilization. The archaeologists found wide streets, and beneath them they dug up clay pipes from an old drainage system. Houses, often three stories high, stood along the road. In the most sacred room of a ruined temple, once a busy place of worship, the workers found the fragments of many small statues. Each one showed a goddess, and each had once been painted in bright colors. The team carried the pieces back to the lab and began the slow work of putting them together. One statue puzzled everyone. Its body came from very old remains, but its head happened to be from a much later, classical time. Someone in ancient days must have found the head, recognized its value, and kept it with great care. When the archaeologists finally reconstructed the figure, they felt amazed. The goddess looked like a very modern woman. She stood about three feet high, her hands rested on her hips, and she wore a full-length skirt that swept the floor. Despite her great age, she was truly graceful. So far, however, no one has been able to discover her identity.","explanation_cn":"课文说 the goddess looked like a very modern woman——奇怪之处在于这位古代女神看上去很现代。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',10,NULL,'choice','{"stem":"What did the archaeologists find in the sacred room?","options":["Nothing at all","A hidden staircase","A pile of modern coins","Fragments of small goddess statues"],"answer_index":3,"audio":"A few years ago, an American team explored an ancient site on a rocky promontory high above the sea. The old city there must have been prosperous, for it once enjoyed a high level of civilization. The archaeologists found wide streets, and beneath them they dug up clay pipes from an old drainage system. Houses, often three stories high, stood along the road. In the most sacred room of a ruined temple, once a busy place of worship, the workers found the fragments of many small statues. Each one showed a goddess, and each had once been painted in bright colors. The team carried the pieces back to the lab and began the slow work of putting them together. One statue puzzled everyone. Its body came from very old remains, but its head happened to be from a much later, classical time. Someone in ancient days must have found the head, recognized its value, and kept it with great care. When the archaeologists finally reconstructed the figure, they felt amazed. The goddess looked like a very modern woman. She stood about three feet high, her hands rested on her hips, and she wore a full-length skirt that swept the floor. Despite her great age, she was truly graceful. So far, however, no one has been able to discover her identity.","explanation_cn":"课文说 the workers found the fragments of many small statues——圣殿里找到的是女神小像的碎片。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l03',10,NULL,'choice','{"stem":"Have the archaeologists discovered the goddess''s identity?","options":["Yes, she was a local farmer","Yes, from a signed letter","No, her identity is still unknown","Yes, she was a famous queen"],"answer_index":2,"audio":"A few years ago, an American team explored an ancient site on a rocky promontory high above the sea. The old city there must have been prosperous, for it once enjoyed a high level of civilization. The archaeologists found wide streets, and beneath them they dug up clay pipes from an old drainage system. Houses, often three stories high, stood along the road. In the most sacred room of a ruined temple, once a busy place of worship, the workers found the fragments of many small statues. Each one showed a goddess, and each had once been painted in bright colors. The team carried the pieces back to the lab and began the slow work of putting them together. One statue puzzled everyone. Its body came from very old remains, but its head happened to be from a much later, classical time. Someone in ancient days must have found the head, recognized its value, and kept it with great care. When the archaeologists finally reconstructed the figure, they felt amazed. The goddess looked like a very modern woman. She stood about three feet high, her hands rested on her hips, and she wore a full-length skirt that swept the floor. Despite her great age, she was truly graceful. So far, however, no one has been able to discover her identity.","explanation_cn":"课文说 so far, no one has been able to discover her identity——她的身份至今不明。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l04',3,1,4,'A Suit and a Secret','一件西装,一个秘密','现在完成时(have/has + 过去分词:结果、经历、刚完成;just/ever/never/yet)vs 现在完成进行时(have/has been + doing:动作从过去持续到现在;for/since/up till now),外加动词 + sth + to sb(explain/describe/say/suggest sth to sb)与 worth + 名词/doing(值得)(原创承载 NCE3 L4 考点·美国人 Danny 瞒着妻子当垃圾清运工)','如今,干体力活的人往往比坐办公室的人挣得多得多。可即便如此,很多人还是向往一份“白领”工作,情愿牺牲高薪,只为享受穿衬衫、打领带上班这份体面。这种奇怪的念头会闹出笑话。就说我邻居 Danny。他给一家大公司当垃圾清运工,已经干了两年,挣得很不错。只有一个问题:他从没跟妻子说过实话。结婚那天,他不好意思把真正的工作解释给她听,只说自己“在公司上班”。那两年他每天的套路都一样:早上穿件干净衬衫出门,拐个弯换上工作服,在垃圾车上干八个小时;回家前冲个澡,再把衬衫换回来。工友们直到现在都替他保守着秘密,妻子也一次都没发现。可情况刚刚变了:Danny 终于找到一份市中心的办公室工作。他只能挣一半的钱,却觉得地位的提升很值这份损失。从今往后,人们会叫他“Reyes 先生”,而不是“Danny”。','{"q":"Listen and answer — What is Danny''s real job?","options":["A garbage collector for a corporation","A bank manager","A school teacher","A truck salesman"],"answer_index":0}'::jsonb,'{"title":"两种“到现在”的时态:现在完成时 & 现在完成进行时","intro":"①现在完成时 have/has + 过去分词——强调到现在为止的结果、经历、刚刚完成(His wife has never found out. / Danny has just taken a new job.),常配 just、ever、never、yet、already。②现在完成进行时 have/has been + doing——强调一个动作从过去一直持续到现在(He has been working here for two years.),常配 for、since、up till now、all day。再记两个难点:③explain / describe / say / suggest 这类词,说“(把某事)对某人……”时要加 to(explain the job to her,不能说 explain her the job);④worth + 名词 / worth + doing = 值得(worth the loss / worth seeing)。","table":{"headers":["时态/结构","强调什么","例子"],"rows":[["现在完成时 have/has done","到现在的结果、经历、刚完成","She has never found out. / He has just left."],["现在完成进行时 have/has been doing","动作从过去持续到现在","He has been working here for two years."],["动词 + sth + to sb","explain/describe/say/suggest 对某人","He explained the job to her."],["worth + 名词 / doing","值得","It is well worth the loss. / worth seeing"]]},"specialRules":[{"rule":"现在完成进行时更看重“一直在做”的过程(常配 for/since);现在完成时更看重“已经做完/做过”的结果或经历(常配 just/ever/never/yet)。","mark":"for/since vs just/ever"},{"rule":"explain / describe / say / suggest 后面说“对某人”要加 to(explain the plan to me),不能像 give 那样直接说 explain me the plan。","mark":"explain … to sb"},{"rule":"美语里“垃圾清运工”常说 garbage collector(英式 dustman);“白领”white-collar 指坐办公室的脑力劳动者,“蓝领”blue-collar 指体力劳动者。","mark":"garbage collector / dustman"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l04',1,NULL,'These days, people who do manual work often earn far more than people who sit in offices. Even so, many workers still dream of a ''white-collar'' job, and they will gladly sacrifice higher pay just for the privilege of wearing a shirt and tie to work.','如今,干体力活的人往往比坐办公室的人挣得多得多。即便如此,很多人还是向往一份“白领”工作,情愿牺牲高薪,只为享受穿衬衫、打领带上班这份体面。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l04',2,NULL,'Take my neighbor Danny. He has been working as a garbage collector for a large corporation for two years now, and he earns very good money. There is only one problem: he has never told his wife the truth.','就说我邻居 Danny。他给一家大公司当垃圾清运工,已经干了两年,挣得很不错。只有一个问题:他从没跟妻子说过实话。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l04',3,NULL,'On their wedding day, he was too embarrassed to explain his real job to her, so he simply said that he worked ''for the Corporation.'' For two years his routine was always the same.','结婚那天,他不好意思把真正的工作解释给她听,只说自己“在公司上班”。那两年,他每天的套路都一样。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l04',4,NULL,'Every morning he left home in a clean shirt, changed into his overalls around the corner, and spent eight hours on the trucks. Before coming home, he took a quick shower and put the shirt back on. His fellow workers have kept his secret up till now, and his wife has never once found out.','早上他穿件干净衬衫出门,拐个弯换上工作服,在垃圾车上干八个小时;回家前冲个澡,再把衬衫换回来。工友们直到现在都替他保密,妻子也一次都没发现。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l04',5,NULL,'But things have just changed. Danny has finally taken an office job downtown. He will earn only half as much, yet he feels the rise in status is well worth the loss. From now on, people will call him ''Mr. Reyes,'' not ''Danny.''','可情况刚刚变了:Danny 终于找到一份市中心的办公室工作。他只能挣一半的钱,却觉得地位的提升很值这份损失。从今往后,人们会叫他“Reyes 先生”,而不是“Danny”。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
