INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l04','downtown','town centre','市中心;美语 downtown,英式 town centre') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
