INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l04','vacation','holiday','假期;美语 vacation,英式 holiday') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l04','be too embarrassed to do','',NULL,'/biː tuː ɪmˈbærəst tuː duː/','He was too embarrassed to tell the truth.','他不好意思说出实话。','She was too embarrassed to ask for help.','她不好意思开口求助。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l04','up till now','',NULL,'/ʌp tɪl naʊ/','His workers have kept the secret up till now.','工友们直到现在都替他保密。','Up till now, no one has complained.','到现在为止,没人抱怨过。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l04','be worth doing','',NULL,'/biː wɜːrθ ˈduːɪŋ/','The rise in status is worth the loss.','地位的提升值这份损失。','This museum is worth visiting.','这座博物馆值得一看。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l04','change into','',NULL,'/tʃeɪndʒ ˈɪntuː/','He changed into his overalls around the corner.','他拐个弯换上了工作服。','Please change into dry clothes.','请换上干衣服。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp1','choice','{"stem":"\"His wife ___ never found out his secret.\"(现在完成时:选助动词,主语第三人称单数)","options":["was","has","is","does"],"answer_index":1,"stem_cn":"他妻子从没发现过他的秘密。","explanation_cn":"“到现在都没发现过”是讲到现在为止的结果,用现在完成时 has + 过去分词(found);主语 wife 是第三人称单数,配 has。✓ His wife has never found out. ✗ is / was / does:配不出现在完成时。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp1','choice','{"stem":"\"Danny ___ just taken a new office job.\"(刚刚做完:现在完成,主语单数选助动词)","options":["was","is","has","will"],"answer_index":2,"stem_cn":"Danny 刚刚找了一份新的办公室工作。","explanation_cn":"“刚刚找了新工作”强调刚完成,用现在完成时 has + taken;主语 Danny 单数配 has。✓ Danny has just taken a new job. ✗ is / was / will:配不出“刚刚完成”的现在完成时。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp1','choice','{"stem":"\"His fellow workers ___ kept his secret up till now.\"(到现在为止:现在完成,主语复数选助动词)","options":["has","were","are","have"],"answer_index":3,"stem_cn":"工友们到现在都替他保守着秘密。","explanation_cn":"“到现在为止一直替他保密”讲到现在的结果,用现在完成时;主语 workers 是复数,配 have。✓ His fellow workers have kept his secret. ✗ has:那是单数用的;✗ are / were:配不出现在完成时。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp1','choice','{"stem":"\"I have never ___ such a strange story before.\"(经历“从没……过”:现在完成,选过去分词)","options":["heard","hearing","hears","hear"],"answer_index":0,"stem_cn":"我以前从没听过这么奇怪的故事。","explanation_cn":"have never + 过去分词表示“从没……过”的经历;hear 的过去分词是 heard。✓ I have never heard such a story. ✗ hear / hearing / hears:都不是过去分词,配不出现在完成时。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp2','choice','{"stem":"\"Danny ___ as a garbage collector for two years now.\"(动作从过去持续到现在:现在完成进行时)","options":["worked","works","is working","has been working"],"answer_index":3,"stem_cn":"Danny 当垃圾清运工已经干了两年了。","explanation_cn":"“当清运工干了两年、一直干到现在”强调动作从过去持续到现在,用现在完成进行时 has been + doing。✓ Danny has been working for two years now. ✗ works / worked / is working:都表达不出“持续了两年到现在”。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp2','choice','{"stem":"\"It ___ all morning, so the streets are still wet.\"(雨一直下到现在:现在完成进行时)","options":["rained","rains","has been raining","is rain"],"answer_index":2,"stem_cn":"雨下了一上午,所以街道还是湿的。","explanation_cn":"“雨下了一上午、下到现在”强调持续的过程,用现在完成进行时。✓ It has been raining all morning. ✗ rains / rained / is rain:都表达不出“一直下到现在”。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp2','choice','{"stem":"\"They ___ for two hours, and they are still not finished.\"(等了很久还没完:现在完成进行时)","options":["are wait","wait","waited","have been waiting"],"answer_index":3,"stem_cn":"他们已经等了两个小时,还是没轮到。","explanation_cn":"“已经等了两小时还在等”强调持续到现在,用现在完成进行时;主语复数配 have。✓ They have been waiting for two hours. ✗ wait / waited / are wait:都不对。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp3','choice','{"stem":"\"Look, the workers ___ three streets so far this morning.\"(强调完成的数量/结果:现在完成时)","options":["have cleaned","cleaned","clean","have been cleaning"],"answer_index":0,"stem_cn":"看,今早工人们已经清扫了三条街了。","explanation_cn":"“到目前为止扫了三条街”强调完成的数量、结果,用现在完成时 have + 过去分词。✓ The workers have cleaned three streets so far. ✗ have been cleaning:那更强调“一直在扫”的过程,这里落点在“扫了几条”的结果;✗ clean / cleaned:配不出现在完成时。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp3','choice','{"stem":"\"The workers are hot and dirty because they ___ since dawn.\"(强调一直在进行的过程:现在完成进行时)","options":["have worked","work","have been working","worked"],"answer_index":2,"stem_cn":"工人们又热又脏,因为他们从天亮就一直在干。","explanation_cn":"“又热又脏,是因为从天亮一直在干”强调持续的过程,用现在完成进行时。✓ They have been working since dawn. ✗ have worked:落点在结果,不如进行式贴“一直在干”;✗ work / worked:时态不对。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp3','choice','{"stem":"\"I ___ this book three times; I know it very well.\"(强调次数/结果:现在完成时)","options":["read","have read","have been reading","am reading"],"answer_index":1,"stem_cn":"这本书我读过三遍,很熟。","explanation_cn":"“读过三遍、很熟”强调次数和结果,用现在完成时。✓ I have read this book three times. ✗ have been reading:那强调“一直在读”的过程;✗ read / am reading:时态不对。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp4','choice','{"stem":"\"On his wedding day, Danny could not explain his real job ___ his wife.\"(动词后接“对某人”时要用的介词)","options":["at","for","to","with"],"answer_index":2,"stem_cn":"结婚那天,Danny 没法把真正的工作解释给妻子听。","explanation_cn":"explain(解释)后面说“对某人”要加 to:explain sth to sb。✓ explain his real job to his wife. ✗ for / with / at:都不是 explain 后接“对某人”的固定介词。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp4','choice','{"stem":"\"Please describe the accident ___ the police officer.\"(动词后接“对某人”时要用的介词)","options":["of","to","with","for"],"answer_index":1,"stem_cn":"请把事故经过描述给警官听。","explanation_cn":"describe(描述)后面说“对某人”要加 to:describe sth to sb。✓ describe the accident to the officer. ✗ for / with / of:搭配不对。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp4','choice','{"stem":"\"She never says anything ___ me about her past.\"(动词后接“对某人”时要用的介词)","options":["to","at","with","for"],"answer_index":0,"stem_cn":"关于她的过去,她从不对我说什么。","explanation_cn":"say(说)后面说“对某人”要加 to:say sth to sb。✓ She never says anything to me. ✗ for / at / with:搭配不对。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp5','choice','{"stem":"\"He feels the higher status is well ___ the loss of money.\"(表示“值得”,用哪个词)","options":["pay","spend","worth","cost"],"answer_index":2,"stem_cn":"他觉得更高的地位很值这份金钱损失。","explanation_cn":"“值得”用 worth,后面直接跟名词:be worth + 名词。✓ well worth the loss of money. ✗ cost / spend / pay:都不表示“值得”这层意思。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp5','choice','{"stem":"\"That old movie is not ___ watching twice.\"(表示“值得做某事”,用哪个词)","options":["afford","worth","cost","pay"],"answer_index":1,"stem_cn":"那部老电影不值得看第二遍。","explanation_cn":"“值得做某事”用 worth + doing。✓ not worth watching twice. ✗ cost / afford / pay:搭配和意思都不对。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp6','choice','{"stem":"\"People who work mainly with their hands do ___ work.\"(“体力的”用哪个词)","options":["royal","mental","equal","manual"],"answer_index":3,"stem_cn":"主要靠双手劳动的人做的是体力工作。","explanation_cn":"靠双手劳动的“体力的、手工的”工作用 manual。✓ manual work 体力活。✗ mental 脑力的;✗ royal 王室的;✗ equal 相等的——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp6','choice','{"stem":"\"He gave up higher pay for the ___ of wearing a suit to work.\"(“特别的好处、荣幸”用哪个词)","options":["danger","privilege","trouble","mistake"],"answer_index":1,"stem_cn":"他放弃了高薪,只为穿西装上班这份体面。","explanation_cn":"“特别的好处、荣幸、体面”用 privilege。✓ the privilege of wearing a suit. ✗ trouble 麻烦;✗ danger 危险;✗ mistake 错误——意思都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',5,'am3_l04_gp6','choice','{"stem":"\"His new office job raised his ___ among his friends.\"(“地位、身份”用哪个词)","options":["distance","weather","status","furniture"],"answer_index":2,"stem_cn":"新的办公室工作提高了他在朋友中的地位。","explanation_cn":"“地位、身份”用 status。✓ raised his status 提高了他的地位。✗ weather 天气;✗ furniture 家具;✗ distance 距离——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',6,NULL,'choice','{"stem":"美语里\"垃圾清运工\"常说:","options":["street-man","garbage collector","clean-worker","dustman"],"answer_index":1,"explanation_cn":"美语里“垃圾清运工”常说 garbage collector(英式说 dustman)。✓ Danny is a garbage collector."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',6,NULL,'choice','{"stem":"manual(work)的意思是:","options":["脑力的","免费的","体力的","危险的"],"answer_index":2,"explanation_cn":"manual = 体力的、手工的。✓ manual work 体力活。\n顺带记:脑力的 = mental;免费的 = free;危险的 = dangerous."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',6,NULL,'choice','{"stem":"sacrifice 的意思是:","options":["庆祝","隐藏","购买","牺牲,舍弃"],"answer_index":3,"explanation_cn":"sacrifice = 牺牲、舍弃。✓ sacrifice higher pay 舍弃更高的工资。\n顺带记:庆祝 = celebrate;购买 = buy;隐藏 = hide."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',6,NULL,'choice','{"stem":"privilege 的意思是:","options":["惩罚","特别的好处,荣幸","债务","借口"],"answer_index":1,"explanation_cn":"privilege = 特别的好处、荣幸、体面。✓ the privilege of wearing a tie 打领带上班这份体面。\n顺带记:惩罚 = punishment;债务 = debt;借口 = excuse."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',6,NULL,'choice','{"stem":"status 的意思是:","options":["地位,身份","天气","距离","家具"],"answer_index":0,"explanation_cn":"status = 地位、身份。✓ the rise in status 地位的提升。\n顺带记:天气 = weather;家具 = furniture;距离 = distance."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',6,NULL,'choice','{"stem":"\"white-collar worker\" 指:","options":["干体力活的工人","坐办公室的脑力劳动者","路上的清洁工","种地的农民"],"answer_index":1,"explanation_cn":"white-collar worker(白领)指坐办公室、穿衬衫打领带的脑力劳动者;干体力活的叫 blue-collar worker(蓝领)。✓ office workers are white-collar workers."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',7,NULL,'cloze','{"stem":"第 1 空","context":"Danny ___1___ as a garbage collector for two years. His wife ___2___ never found out, because he ___3___ his secret from her all this time. But things ___4___ just changed: he has finally taken an office job.","blank_no":1,"options":["has been working","works","worked","is working"],"answer_index":0,"explanation_cn":"“当清运工干了两年、一直到现在”强调持续,用现在完成进行时。✓ Danny has been working for two years."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',7,NULL,'cloze','{"stem":"第 2 空","context":"Danny ___1___ as a garbage collector for two years. His wife ___2___ never found out, because he ___3___ his secret from her all this time. But things ___4___ just changed: he has finally taken an office job.","blank_no":2,"options":["is","has","was","does"],"answer_index":1,"explanation_cn":"“到现在都没发现”用现在完成时;主语 wife 单数配 has。✓ His wife has never found out."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',7,NULL,'cloze','{"stem":"第 3 空","context":"Danny ___1___ as a garbage collector for two years. His wife ___2___ never found out, because he ___3___ his secret from her all this time. But things ___4___ just changed: he has finally taken an office job.","blank_no":3,"options":["has been keeping","keeps","kept","is keeping"],"answer_index":0,"explanation_cn":"“一直替她瞒着这个秘密”强调从过去持续到现在,用现在完成进行时。✓ he has been keeping his secret all this time."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',7,NULL,'cloze','{"stem":"第 4 空","context":"Danny ___1___ as a garbage collector for two years. His wife ___2___ never found out, because he ___3___ his secret from her all this time. But things ___4___ just changed: he has finally taken an office job.","blank_no":4,"options":["has","have","are","were"],"answer_index":1,"explanation_cn":"“事情刚刚变了”用现在完成时;主语 things 复数配 have。✓ things have just changed."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',8,NULL,'choice','{"stem":"What is Danny''s real job?","options":["A school teacher","A truck salesman","A bank manager","A garbage collector for a corporation"],"answer_index":3,"explanation_cn":"课文说 He has been working as a garbage collector for a large corporation——Danny 真正的工作是给一家大公司当垃圾清运工。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',8,NULL,'choice','{"stem":"Why did Danny hide his job from his wife?","options":["She never asked him","He forgot to tell her","He was too embarrassed about it","His boss ordered him to"],"answer_index":2,"explanation_cn":"课文说 he was too embarrassed to explain his real job to her——他因为难为情才瞒着妻子。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',8,NULL,'choice','{"stem":"What has Danny just done?","options":["He has quit all work","He has taken an office job for higher status","He has told the whole town on TV","He has moved to another country"],"answer_index":1,"explanation_cn":"课文说 Danny has finally taken an office job… the rise in status is well worth the loss——他为了地位换了办公室工作。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',9,NULL,'choice','{"stem":"你想说\"他们已经连续工作两个小时了(还在干)\"(现在完成进行,强调持续):","options":["They work for two hours now.","They have been working for two hours.","They have worked for two hours ago.","They are working for two hours."],"answer_index":1,"explanation_cn":"“连续工作两小时还在干”强调持续到现在,用现在完成进行时 have been + doing。✓ They have been working for two hours. 场合:强调一件事从过去一直做到现在。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',9,NULL,'choice','{"stem":"你想说\"我从没把这个秘密告诉过任何人\"(现在完成 tell):","options":["I have never tell anyone this secret.","I have never telled anyone this secret.","I have never told anyone this secret.","I am never telling anyone this secret."],"answer_index":2,"explanation_cn":"“从没告诉过”用现在完成时 have + 过去分词;tell 的过去分词是 told(不是 telled)。✓ I have never told anyone this secret. 场合:讲“至今为止从没做过某事”的经历。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',9,NULL,'choice','{"stem":"你想说\"请把这件事解释给经理听\"(explain 后要加 to):","options":["Please explain the manager this matter.","Please explain for the manager this matter.","Please explain this matter the manager.","Please explain this matter to the manager."],"answer_index":3,"explanation_cn":"explain 后面说“对某人”要加 to:explain sth to sb,不能说 explain sb sth。✓ Please explain this matter to the manager. 场合:请人把某事解释给某人听。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',10,NULL,'choice','{"stem":"status 的意思是:","options":["地位,身份","天气","家具","距离"],"answer_index":0,"explanation_cn":"status = 地位、身份。✓ the rise in status 地位的提升。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',10,NULL,'choice','{"stem":"sacrifice 的意思是:","options":["购买","牺牲,舍弃","庆祝","隐藏"],"answer_index":1,"explanation_cn":"sacrifice = 牺牲、舍弃。✓ sacrifice higher pay 舍弃更高的工资。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',10,NULL,'choice','{"stem":"\"They ___ since early morning and are still busy.\"(强调持续:现在完成进行时)","options":["worked","have worked","have been working","work"],"answer_index":2,"stem_cn":"他们从一大早就一直在干,现在还忙着。","explanation_cn":"“从一大早一直干到现在还忙着”强调持续,用现在完成进行时。✓ They have been working since early morning. ✗ have worked / work / worked:表达不出“一直在干”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',10,NULL,'choice','{"stem":"\"His wife ___ never found out the truth.\"(现在完成时:选助动词)","options":["does","was","is","has"],"answer_index":3,"stem_cn":"他妻子从没发现过真相。","explanation_cn":"“到现在都没发现真相”用现在完成时;主语 wife 单数配 has。✓ His wife has never found out. ✗ is / was / does:配不出现在完成时。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',10,NULL,'choice','{"stem":"\"be worth doing\" 的意思是:","options":["害怕做…","值得做…","不许做…","忘记做…"],"answer_index":1,"explanation_cn":"be worth doing = 值得做某事。✓ This museum is worth visiting 这座博物馆值得一看。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',10,NULL,'choice','{"stem":"\"up till now\" 的意思是:","options":["直到现在为止","从明天起","很久以前","偶尔"],"answer_index":0,"explanation_cn":"up till now = 直到现在为止。✓ Up till now, no one has found out 到现在为止,没人发现。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',10,NULL,'choice','{"stem":"Why did Danny hide his job from his wife?","options":["He worked in another city","She hated garbage trucks","He was too embarrassed to tell her the truth","He did not have any job"],"answer_index":2,"passage":"These days, people who do manual work often earn far more than people who sit in offices. Even so, many workers still dream of a ''white-collar'' job, and they will gladly sacrifice higher pay just for the privilege of wearing a shirt and tie to work. This strange idea can lead to some funny situations. Take my neighbor Danny. He has been working as a garbage collector for a large corporation for two years now, and he earns very good money. There is only one problem: he has never told his wife the truth. On their wedding day, he was too embarrassed to explain his real job to her, so he simply said that he worked ''for the Corporation.'' For two years his routine was always the same. Every morning he left home in a clean shirt, changed into his overalls around the corner, and spent eight hours on the trucks. Before coming home, he took a quick shower and put the shirt back on. His fellow workers have kept his secret up till now, and his wife has never once found out. But things have just changed. Danny has finally taken an office job downtown. He will earn only half as much, yet he feels the rise in status is well worth the loss. From now on, people will call him ''Mr. Reyes,'' not ''Danny.''","explanation_cn":"课文说 he was too embarrassed to explain his real job to her——他因为太难为情才瞒着妻子。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',10,NULL,'choice','{"stem":"Why is Danny happy to earn less money now?","options":["He feels the higher status is worth it","He wants to retire soon","He hates having money","He plans to move away"],"answer_index":0,"passage":"These days, people who do manual work often earn far more than people who sit in offices. Even so, many workers still dream of a ''white-collar'' job, and they will gladly sacrifice higher pay just for the privilege of wearing a shirt and tie to work. This strange idea can lead to some funny situations. Take my neighbor Danny. He has been working as a garbage collector for a large corporation for two years now, and he earns very good money. There is only one problem: he has never told his wife the truth. On their wedding day, he was too embarrassed to explain his real job to her, so he simply said that he worked ''for the Corporation.'' For two years his routine was always the same. Every morning he left home in a clean shirt, changed into his overalls around the corner, and spent eight hours on the trucks. Before coming home, he took a quick shower and put the shirt back on. His fellow workers have kept his secret up till now, and his wife has never once found out. But things have just changed. Danny has finally taken an office job downtown. He will earn only half as much, yet he feels the rise in status is well worth the loss. From now on, people will call him ''Mr. Reyes,'' not ''Danny.''","explanation_cn":"课文说 he feels the rise in status is well worth the loss——他觉得地位的提升值得,所以甘愿少挣钱。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',10,NULL,'choice','{"stem":"What did Danny change into every morning?","options":["A doctor''s coat","His work overalls","A police uniform","A school uniform"],"answer_index":1,"audio":"These days, people who do manual work often earn far more than people who sit in offices. Even so, many workers still dream of a ''white-collar'' job, and they will gladly sacrifice higher pay just for the privilege of wearing a shirt and tie to work. This strange idea can lead to some funny situations. Take my neighbor Danny. He has been working as a garbage collector for a large corporation for two years now, and he earns very good money. There is only one problem: he has never told his wife the truth. On their wedding day, he was too embarrassed to explain his real job to her, so he simply said that he worked ''for the Corporation.'' For two years his routine was always the same. Every morning he left home in a clean shirt, changed into his overalls around the corner, and spent eight hours on the trucks. Before coming home, he took a quick shower and put the shirt back on. His fellow workers have kept his secret up till now, and his wife has never once found out. But things have just changed. Danny has finally taken an office job downtown. He will earn only half as much, yet he feels the rise in status is well worth the loss. From now on, people will call him ''Mr. Reyes,'' not ''Danny.''","explanation_cn":"课文说 he changed into his overalls——每天早上他换上工作服去干活。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l04',10,NULL,'choice','{"stem":"Who kept Danny''s secret?","options":["His children","The local newspaper","His wife''s family","His fellow workers"],"answer_index":3,"audio":"These days, people who do manual work often earn far more than people who sit in offices. Even so, many workers still dream of a ''white-collar'' job, and they will gladly sacrifice higher pay just for the privilege of wearing a shirt and tie to work. This strange idea can lead to some funny situations. Take my neighbor Danny. He has been working as a garbage collector for a large corporation for two years now, and he earns very good money. There is only one problem: he has never told his wife the truth. On their wedding day, he was too embarrassed to explain his real job to her, so he simply said that he worked ''for the Corporation.'' For two years his routine was always the same. Every morning he left home in a clean shirt, changed into his overalls around the corner, and spent eight hours on the trucks. Before coming home, he took a quick shower and put the shirt back on. His fellow workers have kept his secret up till now, and his wife has never once found out. But things have just changed. Danny has finally taken an office job downtown. He will earn only half as much, yet he feels the rise in status is well worth the loss. From now on, people will call him ''Mr. Reyes,'' not ''Danny.''","explanation_cn":"课文说 His fellow workers have kept his secret up till now——是工友们一直替他保守秘密。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l05',3,1,5,'The Exact Facts','确切数字','过去完成时(had + 过去分词:表示''过去的过去'',比另一个过去动作更早)及其被动(had been + 过去分词),外加否定副词置于句首时的倒装(Not only had he... / Never had I... / Hardly had...);官方 Key structures 的冠词 a(n)/the 用法并入 gp5 作复习(原创承载 NCE3 L5 考点·编辑逼记者要确切数字,记者数台阶时被捕入狱)','美国杂志的编辑有时为了给读者确切的事实和数字,会走极端。去年,一家知名杂志派了一名记者出国,写一篇有关某遥远国家总统所住宏伟宫殿的报道。稿子寄到时,编辑读了第一句就拒绝发表。文章开头写道:“数百级台阶通向环绕宫殿的高墙。”编辑立刻给记者发传真,要他查清台阶的确切级数和墙的高度。记者动身去弄这些重要数字,可几周过去了,毫无回音。与此同时,杂志马上就要付印,编辑越来越不耐烦。他又发了三封传真,警告说若再不回,就解雇他。见还是没回音,编辑最终照原样发表了那篇文章。一周后,一封传真终于来了。这个可怜的记者不但被捕,还被投进了监狱。他只获准发出一条消息:他是在数那通向十五英尺高墙的1,084级台阶时被捕的。','{"q":"Listen and answer — Why did the editor first refuse to publish the article?","options":["It gave no exact numbers or facts","It was far too short","It had no photos","It praised the president too much"],"answer_index":0}'::jsonb,'{"title":"“过去的过去”:过去完成时 & 它的被动 + 否定词倒装","intro":"①过去完成时 had + 过去分词——讲“比某个过去动作更早发生”的事,也叫“过去的过去”(When the article arrived 是过去;the magazine had sent a journalist 更早)。②被动就写成 had been + 过去分词(the poor man had been arrested 被捕;had been sent to prison 被关进监狱)。③否定副词/词组放句首(Not only、Never、Hardly、Seldom),后面要倒装——把 had/have/did 提到前面,像问句那样的语序(Not only had he been arrested… / Never had I seen…)。④本课官方还复习冠词:a(n) 泛指、the 特指。","table":{"headers":["结构","用来讲","例子"],"rows":[["过去完成时 had done","比另一个过去动作更早发生","The magazine had sent a reporter before the article arrived."],["过去完成被动 had been done","更早发生、且是“被……”","The man had been arrested and sent to prison."],["否定词句首 + 倒装","Not only / Never / Hardly 放句首","Not only had he been arrested, but also thrown into prison."],["冠词 a(n) / the","泛指 / 特指","an article about the palace"]]},"specialRules":[{"rule":"两个过去动作,先发生的那个用过去完成时 had done,后发生的用一般过去时(After he had counted the steps, he wrote down the number)。","mark":"had done vs did"},{"rule":"Not only / Never / Hardly / Seldom 放句首,后面必须倒装:把 had/have/does/did 提到主语前面,像问句语序(Never had I seen…),这样用来加强语气。","mark":"Not only had…"},{"rule":"美语里“传真”说 fax;“解雇”口语常说 fire(sb)。本课已按美语写。","mark":"fax / fire"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l05',1,NULL,'Editors of American magazines sometimes go to extremes to give their readers exact facts and statistics. Last year, a well-known magazine had sent one of its journalists abroad to write an article about the grand palace where a distant country''s president lived.','美国杂志的编辑有时为了给读者确切的事实和数字,会走极端。去年,一家知名杂志派了一名记者出国,写一篇有关某遥远国家总统所住宏伟宫殿的报道。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l05',2,NULL,'When the article arrived, the editor read the very first line and refused to publish it. The article began: ''Hundreds of steps lead up to the high wall that surrounds the palace.'' At once the editor faxed the journalist and told him to find the exact number of steps and the height of the wall.','稿子寄到时,编辑读了第一句就拒绝发表。文章开头写道:“数百级台阶通向环绕宫殿的高墙。”编辑立刻给记者发传真,要他查清台阶的确切级数和墙的高度。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l05',3,NULL,'The journalist set out to obtain these important facts, but weeks passed and no reply came. Meanwhile, the magazine was about to go to press, and the editor grew more and more impatient.','记者动身去弄这些重要数字,可几周过去了,毫无回音。与此同时,杂志马上就要付印,编辑越来越不耐烦。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l05',4,NULL,'He sent three more faxes, warning that the journalist would be fired if he did not answer soon. When no answer came, the editor finally published the article just as it had originally been written.','他又发了三封传真,警告说若再不回就解雇他。见还是没回音,编辑最终照原样发表了那篇文章。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l05',5,NULL,'A week later, a fax at last arrived. Not only had the poor journalist been arrested, but he had also been thrown into prison. He had been arrested while he was counting the 1,084 steps that led up to the fifteen-foot wall around the palace.','一周后,一封传真终于来了。这个可怜的记者不但被捕,还被投进了监狱。他是在数那通向十五英尺高墙的1,084级台阶时被捕的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
