INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l05','go to extremes','',NULL,'/ɡoʊ tuː ɪkˈstriːmz/','Editors sometimes go to extremes for exact facts.','编辑有时为了确切的事实会走极端。','Don''t go to extremes over a small mistake.','别为一个小错走极端。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l05','set out to do','',NULL,'/set aʊt tuː duː/','He set out to obtain the important facts.','他动身去弄那些重要数字。','They set out to build a new school.','他们着手建一所新学校。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l05','go to press','',NULL,'/ɡoʊ tuː pres/','The magazine was about to go to press.','杂志马上就要付印了。','The paper goes to press at midnight.','报纸午夜付印。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l05','not only ... but also','',NULL,'/nɑːt ˈoʊnli bʌt ˈɔːlsoʊ/','He was not only arrested but also jailed.','他不但被捕,还被关了起来。','She is not only smart but also kind.','她不但聪明,而且善良。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp1','choice','{"stem":"\"The magazine ___ a journalist abroad long before the article arrived.\"(比过去更早发生:过去完成时)","options":["had sent","sent","has sent","sends"],"answer_index":0,"stem_cn":"早在稿子寄到之前,杂志就已派了一名记者出国。","explanation_cn":"“稿子寄到”是过去,“派记者出国”比它更早,是“过去的过去”,用过去完成时 had + 过去分词。✓ the magazine had sent a journalist. ✗ sent:那和“寄到”同为过去,分不出先后;✗ has sent / sends:时态不对。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp1','choice','{"stem":"\"When the editor read the first line, he knew the journalist ___ the wrong kind of article.\"(读之前就已写好,更早:过去完成时)","options":["has written","had written","wrote","writes"],"answer_index":1,"stem_cn":"编辑读第一句就知道记者写错了方向。","explanation_cn":"“读第一句”是过去,“写好这篇文章”更早,用过去完成时。✓ the journalist had written the wrong article. ✗ wrote:分不出更早;✗ writes / has written:时态不对。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp1','choice','{"stem":"\"He explained that he ___ the palace steps before the police stopped him.\"(被拦之前先在数,更早:过去完成时)","options":["had counted","counts","counted","has counted"],"answer_index":0,"stem_cn":"他解释说,警察拦住他之前,他正数着宫殿的台阶。","explanation_cn":"“警察拦住他”是过去,“他在数台阶”这件事发生在更早/之前,用过去完成时。✓ he had counted the steps before the police stopped him. ✗ counted:分不出先后;✗ counts / has counted:时态不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp1','choice','{"stem":"\"By June the editor still had not heard from the man, who ___ abroad back in April.\"(四月出国更早:过去完成时)","options":["went","goes","had gone","has gone"],"answer_index":2,"stem_cn":"到六月编辑还没收到那人的消息,他四月就出国了。","explanation_cn":"“到六月还没消息”是过去,“四月出国”更早,用过去完成时。✓ the man had gone abroad in April. ✗ went:分不出更早;✗ goes / has gone:时态不对。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp2','choice','{"stem":"\"The editor finally published the article just as it ___ at first.\"(更早发生、且是“被写成”:过去完成被动)","options":["has been written","wrote","was written","had been written"],"answer_index":3,"stem_cn":"编辑最终照它起初被写成的原样发表了。","explanation_cn":"文章是“被写成”的(被动),而且比“发表”更早,用过去完成被动 had been + 过去分词。✓ just as it had been written. ✗ was written:只是一般过去的被动,分不出更早;✗ has been written / wrote:时态不对。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp2','choice','{"stem":"\"A week later they learned that the reporter ___ by the local police.\"(“被逮捕”、且更早:过去完成被动)","options":["has arrested","was arresting","had been arrested","arrested"],"answer_index":2,"stem_cn":"一周后他们得知,记者已被当地警察逮捕。","explanation_cn":"记者是“被逮捕”(被动),且比“得知”更早,用过去完成被动。✓ the reporter had been arrested. ✗ arrested:主动、且分不出更早;✗ was arresting / has arrested:时态或语态不对。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp2','choice','{"stem":"\"The poor man ___ into prison before he could send any news.\"(“被投入监狱”、且更早:过去完成被动)","options":["has thrown","had been thrown","threw","was throwing"],"answer_index":1,"stem_cn":"还没来得及送出消息,这可怜人就已被投进监狱。","explanation_cn":"“被投进监狱”是被动,且发生在“送出消息”之前,用过去完成被动。✓ the man had been thrown into prison. ✗ threw:主动;✗ was throwing / has thrown:时态或语态不对。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp3','choice','{"stem":"\"Not only ___ the poor journalist been arrested, but also thrown into prison.\"(Not only 放句首,引起倒装)","options":["had","did","was","has"],"answer_index":0,"stem_cn":"这可怜的记者不但被捕,还被投进了监狱。","explanation_cn":"Not only 放在句首,后面要倒装:把 had 提到 the journalist 前面,像问句那样的语序 Not only had he been arrested…。✓ Not only had the journalist been arrested. ✗ did / was / has:配不出 had been arrested 这个结构。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp3','choice','{"stem":"\"Never ___ I seen such a strange excuse until that day.\"(Never 放句首,引起倒装)","options":["was","had","have","did"],"answer_index":1,"stem_cn":"直到那天,我才见过这么奇怪的借口。","explanation_cn":"Never 放在句首要倒装:把 had 提到 I 前面,写成 Never had I seen…;句尾 until that day 提示这是“过去的过去”。✓ Never had I seen such an excuse. ✗ have:那要配现在完成 Never have I seen,但这里讲过去;✗ was / did:配不出。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp3','choice','{"stem":"\"Hardly ___ the editor published the article when the fax finally arrived.\"(Hardly 放句首,引起倒装)","options":["did","was","had","he had"],"answer_index":2,"stem_cn":"编辑刚发表文章,传真就终于到了。","explanation_cn":"Hardly 放句首要倒装:Hardly had the editor published… when…(刚一……就……)。✓ Hardly had the editor published the article. ✗ he had:句首倒装后不再是正常语序;✗ did / was:配不出这个结构。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp4','choice','{"stem":"\"The journalist ___ before the editor even arrived at the office.\"(先离开,发生更早:过去完成时)","options":["left","leaves","has left","had left"],"answer_index":3,"stem_cn":"编辑还没到办公室,记者就已经走了。","explanation_cn":"“编辑到办公室”是过去,“记者离开”更早,用过去完成时。✓ the journalist had left before the editor arrived. ✗ left:分不出更早;✗ leaves / has left:时态不对。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp4','choice','{"stem":"\"After he ___ all the steps, he wrote down the exact number.\"(先数完,再写下:数用过去完成)","options":["had counted","counts","counting","was counted"],"answer_index":0,"stem_cn":"他把所有台阶数完之后,写下了确切的数字。","explanation_cn":"After 引导的“先数完”发生在“写下数字”之前,先发生的用过去完成时。✓ After he had counted all the steps, he wrote it down. ✗ counts / counting / was counted:时态或语态不对。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp4','choice','{"stem":"\"The editor grew impatient and finally ___ the article himself.\"(叙事主线、后发生:一般过去)","options":["had published","published","was publishing","publishes"],"answer_index":1,"stem_cn":"编辑不耐烦起来,最后自己把文章发表了。","explanation_cn":"这是叙事主线上后发生、已完成的动作,用一般过去时,不用过去完成。✓ the editor finally published the article. ✗ had published:这里没有“比另一个过去更早”的需要;✗ publishes / was publishing:时态不对。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp5','choice','{"stem":"\"The editor wanted to know ___ exact number of steps.\"(特指“那个唯一确定的数字”,用哪个冠词)","options":["a","不填","the","an"],"answer_index":2,"stem_cn":"编辑想知道那个确切的台阶数。","explanation_cn":"“那个唯一确定的确切数字”是特指,用定冠词 the。✓ the exact number of steps. ✗ a / an:那是泛指;✗ 不填:这里需要冠词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp5','choice','{"stem":"\"The journalist was writing ___ article about a famous palace.\"(泛指、单数可数、后面词以元音开头,用哪个冠词)","options":["a","the","不填","an"],"answer_index":3,"stem_cn":"记者正写一篇有关著名宫殿的报道。","explanation_cn":"“一篇报道”是泛指、单数可数;后面 article 以元音音开头,所以用 an。✓ an article about a palace. ✗ a:元音音前不用 a;✗ the:这里是泛指不是特指;✗ 不填:需要冠词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp6','choice','{"stem":"\"A person who writes news reports for a magazine is a ___.\"(“记者”用哪个词)","options":["journalist","farmer","dentist","pilot"],"answer_index":0,"stem_cn":"为杂志写新闻报道的人是记者。","explanation_cn":"为杂志、报纸写新闻报道的人叫 journalist(记者)。✓ a journalist writes news reports. ✗ farmer 农民;✗ dentist 牙医;✗ pilot 飞行员——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp6','choice','{"stem":"\"The editor grew ___ because the journalist would not reply.\"(“不耐烦的”用哪个词)","options":["grateful","generous","cheerful","impatient"],"answer_index":3,"stem_cn":"记者迟迟不回,编辑变得不耐烦。","explanation_cn":"“等不及、不耐烦的”用 impatient。✓ the editor grew impatient. ✗ grateful 感激的;✗ cheerful 高兴的;✗ generous 慷慨的——意思都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',5,'am3_l05_gp6','choice','{"stem":"\"The magazine printed the article just as it was ___ written.\"(“起初、原先”用哪个词)","options":["rarely","hardly","originally","luckily"],"answer_index":2,"stem_cn":"杂志照文章起初被写成的样子发表了。","explanation_cn":"“起初、原先”用 originally。✓ just as it was originally written 照它起初写的样子。✗ luckily 幸运地;✗ hardly 几乎不;✗ rarely 很少——意思都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',6,NULL,'choice','{"stem":"statistics 的意思是:","options":["语法","政治","统计数字","距离"],"answer_index":2,"explanation_cn":"statistics = 统计数字、数据。✓ exact facts and statistics 确切的事实与数据。\n顺带记:政治 = politics;语法 = grammar;距离 = distance."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',6,NULL,'choice','{"stem":"impatient 的意思是:","options":["害怕的","不耐烦的","很耐心的","高兴的"],"answer_index":1,"explanation_cn":"impatient = 不耐烦的。✓ the editor grew impatient 编辑不耐烦起来。\n顺带记:很耐心的 = patient;高兴的 = happy;害怕的 = afraid."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',6,NULL,'choice','{"stem":"fire(此处动词)的意思是:","options":["解雇,开除","培训","表扬","雇用"],"answer_index":0,"explanation_cn":"fire(动词)= 解雇、开除。✓ he would be fired 他会被解雇。\n顺带记:雇用 = hire;表扬 = praise;培训 = train."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',6,NULL,'choice','{"stem":"originally 的意思是:","options":["故意地","突然","幸运地","起初,原先"],"answer_index":3,"explanation_cn":"originally = 起初、原先。✓ as it was originally written 照它起初写的样子。\n顺带记:突然 = suddenly;幸运地 = luckily;故意地 = on purpose."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',6,NULL,'choice','{"stem":"\"go to extremes\" 的意思是:","options":["放弃努力","走极端","准时到","去远方"],"answer_index":1,"explanation_cn":"go to extremes = 走极端、做得过头。✓ editors go to extremes for facts 编辑为了数字走极端。\n顺带记:去远方 = go far away;准时到 = arrive on time;放弃 = give up."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',6,NULL,'choice','{"stem":"editor 的意思是:","options":["编辑","记者","作者","读者"],"answer_index":0,"explanation_cn":"editor = 编辑(决定登不登、怎么改稿的人);写稿的人叫 journalist(记者)。✓ the editor refused to publish it 编辑拒绝发表。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',7,NULL,'cloze','{"stem":"第 1 空","context":"When the editor read the first line, he knew the journalist ___1___ the wrong kind of article. The magazine finally published it just as it ___2___ at first. A week later they learned that the reporter ___3___ by the police. Not only ___4___ he been arrested, but also thrown into prison.","blank_no":1,"options":["wrote","had written","writes","has written"],"answer_index":1,"explanation_cn":"“读第一句”是过去,记者“写好这篇”更早,用过去完成时。✓ the journalist had written the wrong article."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',7,NULL,'cloze','{"stem":"第 2 空","context":"When the editor read the first line, he knew the journalist ___1___ the wrong kind of article. The magazine finally published it just as it ___2___ at first. A week later they learned that the reporter ___3___ by the police. Not only ___4___ he been arrested, but also thrown into prison.","blank_no":2,"options":["had been written","was written","is written","wrote"],"answer_index":0,"explanation_cn":"文章是“被写成”的,且比“发表”更早,用过去完成被动。✓ just as it had been written."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',7,NULL,'cloze','{"stem":"第 3 空","context":"When the editor read the first line, he knew the journalist ___1___ the wrong kind of article. The magazine finally published it just as it ___2___ at first. A week later they learned that the reporter ___3___ by the police. Not only ___4___ he been arrested, but also thrown into prison.","blank_no":3,"options":["arrested","had been arrested","is arrested","arrests"],"answer_index":1,"explanation_cn":"记者是“被逮捕”,且比“得知”更早,用过去完成被动。✓ the reporter had been arrested."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',7,NULL,'cloze','{"stem":"第 4 空","context":"When the editor read the first line, he knew the journalist ___1___ the wrong kind of article. The magazine finally published it just as it ___2___ at first. A week later they learned that the reporter ___3___ by the police. Not only ___4___ he been arrested, but also thrown into prison.","blank_no":4,"options":["had","did","was","has"],"answer_index":0,"explanation_cn":"Not only 放句首要倒装:把 had 提前,写成 Not only had he been arrested…。✓ Not only had he been arrested."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',8,NULL,'choice','{"stem":"Why did the editor refuse to publish the first article?","options":["It praised the president","It gave no exact facts or numbers","It was far too long","It had no title"],"answer_index":1,"explanation_cn":"课文说编辑读第一句(只有“数百级台阶”)就拒登,因为它没有确切的台阶数和墙高——他要的是 exact facts。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',8,NULL,'choice','{"stem":"Why did the editor grow impatient?","options":["His fax machine had broken","The president had called him","The journalist would not reply and the magazine had to go to press","He had lost the article"],"answer_index":2,"explanation_cn":"课文说 the magazine would soon go to press… the editor grew more and more impatient——记者不回、杂志又要付印,所以编辑不耐烦。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',8,NULL,'choice','{"stem":"What had happened to the journalist?","options":["He had been arrested and sent to prison","He had gone on vacation","He had lost the palace address","He had quit his job"],"answer_index":0,"explanation_cn":"课文说 the poor journalist had been arrested… had been thrown into prison——记者被捕并被关进了监狱。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',9,NULL,'choice','{"stem":"你想说\"我到的时候他已经离开了\"(过去完成:更早发生):","options":["When I arrived, he already leaves.","When I had arrived, he already left.","When I arrived, he had already left.","When I arrived, he was already leaving away."],"answer_index":2,"explanation_cn":"“我到”是过去,“他离开”更早,更早的那个用过去完成 had left。✓ When I arrived, he had already left. 场合:讲“我到之前,他早走了”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',9,NULL,'choice','{"stem":"你想说\"我从没见过这么奇怪的借口\"(Never 放句首,倒装):","options":["Never had I seen such a strange excuse.","Never have I saw such a strange excuse.","Never did I saw such a strange excuse.","Never I had seen such a strange excuse."],"answer_index":0,"explanation_cn":"Never 放句首要倒装:把 had 提到 I 前面,写成 Never had I seen…。✓ Never had I seen such a strange excuse. 场合:用否定词开头、加强“从没见过”的语气。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',9,NULL,'choice','{"stem":"你想说\"那篇文章按原样发表了\"(过去完成被动):","options":["The article had been publish just as it wrote.","The article was publish just as it had been wrote.","The article published just as it had written.","The article was published just as it had been written."],"answer_index":3,"explanation_cn":"“被发表”用被动 was published;“被写成”比它更早,用过去完成被动 had been written。✓ The article was published just as it had been written. 场合:讲一篇稿子照原样被发表。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',10,NULL,'choice','{"stem":"journalist 的意思是:","options":["新闻记者","作家","编辑","读者"],"answer_index":0,"explanation_cn":"journalist = 新闻记者(写稿的人);editor 是编辑(改稿、决定发表的人)。✓ the journalist wrote the article."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',10,NULL,'choice','{"stem":"impatient 的意思是:","options":["高兴的","不耐烦的","害怕的","很耐心的"],"answer_index":1,"explanation_cn":"impatient = 不耐烦的。✓ the editor grew impatient 编辑不耐烦起来。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',10,NULL,'choice','{"stem":"\"The editor published the piece just as the writer ___ it at first.\"(先写、后发表:过去完成)","options":["had written","was writing","writes","wrote"],"answer_index":0,"stem_cn":"编辑照作者起初写的原样发表了文章。","explanation_cn":"“发表”是过去,“作者起初写好”更早,用过去完成时。✓ just as the writer had written it at first. ✗ wrote / writes / was writing:分不出更早或时态不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',10,NULL,'choice','{"stem":"\"Not only ___ he been arrested, but also thrown into prison.\"(Not only 放句首,倒装)","options":["did","was","has","had"],"answer_index":3,"stem_cn":"他不但被捕,还被投进了监狱。","explanation_cn":"Not only 放句首要倒装:把 had 提到 he 前面,写成 Not only had he been arrested…。✓ Not only had he been arrested. ✗ did / was / has:配不出这个结构。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',10,NULL,'choice','{"stem":"\"go to extremes\" 的意思是:","options":["放弃努力","走极端","准时到","去远方"],"answer_index":1,"explanation_cn":"go to extremes = 走极端、做过头。✓ editors go to extremes for facts."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',10,NULL,'choice','{"stem":"\"set out to do\" 的意思是:","options":["着手去做…","忘记做…","拒绝做…","假装做…"],"answer_index":0,"explanation_cn":"set out to do = 着手、动身去做某事。✓ He set out to obtain the facts 他着手去弄那些数字。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',10,NULL,'choice','{"stem":"Why did the editor send the journalist a fax?","options":["To praise his article","To fire him at once","To ask for the exact number of steps and the wall''s height","To cancel the story"],"answer_index":2,"passage":"Editors of American magazines sometimes go to extremes to give their readers exact facts and statistics. Last year, a well-known magazine had sent one of its journalists abroad to write an article about the grand palace where a distant country''s president lived. When the article arrived, the editor read the very first line and refused to publish it. The article began: ''Hundreds of steps lead up to the high wall that surrounds the palace.'' At once the editor faxed the journalist and told him to find the exact number of steps and the height of the wall. The journalist set out to obtain these important facts, but weeks passed and no reply came. Meanwhile, the magazine was about to go to press, and the editor grew more and more impatient. He sent three more faxes, warning that the journalist would be fired if he did not answer soon. When no answer came, the editor finally published the article just as it had originally been written. A week later, a fax at last arrived. Not only had the poor journalist been arrested, but he had also been thrown into prison. He had been allowed to send only one message: he had been arrested while he was counting the 1,084 steps that led up to the fifteen-foot wall around the palace.","explanation_cn":"课文说编辑发传真 told him to find the exact number of steps and the height of the wall——他要的是确切的台阶数和墙高。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',10,NULL,'choice','{"stem":"What was the journalist doing when he was arrested?","options":["Counting the 1,084 steps up to the wall","Taking photos of the president","Painting the palace wall","Selling the magazine"],"answer_index":0,"passage":"Editors of American magazines sometimes go to extremes to give their readers exact facts and statistics. Last year, a well-known magazine had sent one of its journalists abroad to write an article about the grand palace where a distant country''s president lived. When the article arrived, the editor read the very first line and refused to publish it. The article began: ''Hundreds of steps lead up to the high wall that surrounds the palace.'' At once the editor faxed the journalist and told him to find the exact number of steps and the height of the wall. The journalist set out to obtain these important facts, but weeks passed and no reply came. Meanwhile, the magazine was about to go to press, and the editor grew more and more impatient. He sent three more faxes, warning that the journalist would be fired if he did not answer soon. When no answer came, the editor finally published the article just as it had originally been written. A week later, a fax at last arrived. Not only had the poor journalist been arrested, but he had also been thrown into prison. He had been allowed to send only one message: he had been arrested while he was counting the 1,084 steps that led up to the fifteen-foot wall around the palace.","explanation_cn":"课文说 he had been arrested while he was counting the 1,084 steps——他被捕时正在数那1,084级台阶。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',10,NULL,'choice','{"stem":"What did the editor finally do with the article?","options":["He rewrote it himself","He gave it to another magazine","He published it just as it was first written","He threw it away"],"answer_index":2,"audio":"Editors of American magazines sometimes go to extremes to give their readers exact facts and statistics. Last year, a well-known magazine had sent one of its journalists abroad to write an article about the grand palace where a distant country''s president lived. When the article arrived, the editor read the very first line and refused to publish it. The article began: ''Hundreds of steps lead up to the high wall that surrounds the palace.'' At once the editor faxed the journalist and told him to find the exact number of steps and the height of the wall. The journalist set out to obtain these important facts, but weeks passed and no reply came. Meanwhile, the magazine was about to go to press, and the editor grew more and more impatient. He sent three more faxes, warning that the journalist would be fired if he did not answer soon. When no answer came, the editor finally published the article just as it had originally been written. A week later, a fax at last arrived. Not only had the poor journalist been arrested, but he had also been thrown into prison. He had been allowed to send only one message: he had been arrested while he was counting the 1,084 steps that led up to the fifteen-foot wall around the palace.","explanation_cn":"课文说 the editor finally published the article just as it had originally been written——他照原样发表了。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l05',10,NULL,'choice','{"stem":"Where was the journalist when he sent his last message?","options":["In the editor''s office","At the palace gate","On a plane home","In prison"],"answer_index":3,"audio":"Editors of American magazines sometimes go to extremes to give their readers exact facts and statistics. Last year, a well-known magazine had sent one of its journalists abroad to write an article about the grand palace where a distant country''s president lived. When the article arrived, the editor read the very first line and refused to publish it. The article began: ''Hundreds of steps lead up to the high wall that surrounds the palace.'' At once the editor faxed the journalist and told him to find the exact number of steps and the height of the wall. The journalist set out to obtain these important facts, but weeks passed and no reply came. Meanwhile, the magazine was about to go to press, and the editor grew more and more impatient. He sent three more faxes, warning that the journalist would be fired if he did not answer soon. When no answer came, the editor finally published the article just as it had originally been written. A week later, a fax at last arrived. Not only had the poor journalist been arrested, but he had also been thrown into prison. He had been allowed to send only one message: he had been arrested while he was counting the 1,084 steps that led up to the fifteen-foot wall around the palace.","explanation_cn":"课文说他被关进监狱后,只获准发出一条消息——所以发最后那条消息时他人在监狱里。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
